var e=JSON.parse('[{"title":"Modul 0: Homelab — Deine IT-Support-Übungsumgebung","level":1,"module":0,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2 / Windows Server 2022","sources":[{"url":"https://en.wikipedia.org/wiki/VMware_Workstation","abrufdatum":"2026-10-19"},{"url":"https://www.free-codecs.com/download/vmware-workstation-pro.htm","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/paths/windows-server-network-infrastructure/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-server/get-started/evaluation","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"VMware Workstation Pro ist nicht kostenlos","symptom":"VMware verlangt einen Product Key bei der Installation","ursache":"Falsche Version installiert (z. B. VMware Player oder alte Version)","diagnose_schritte":["Überprüfe die installierte Version: VMware → Help → About","Prüfe, ob du die aktuelle Version (26H1u1 oder neuer) hast","Überprüfe die Download-Quelle (muss support.broadcom.com sein)"],"loesung":"Neueste Version von https://support.broadcom.com downloaden und installieren","praevention":"Immer die aktuelle Version vom offiziellen Broadcom-Portal verwenden\\n\\n**Quelle:** https://en.wikipedia.org/wiki/VMware_Workstation (abgerufen 2026-10-19)\\n\\n---"},{"titel":"Windows 11 Evaluation läuft ab","symptom":"Windows meldet \\"Windows ist nicht aktiviert\\" nach 180 Tagen","ursache":"Evaluation-Laufzeit abgelaufen","diagnose_schritte":["`slmgr /xpr` in Eingabeaufforderung als Administrator ausführen","Zeigt \\"Windows ist dauerhaft aktiviert\\" oder Ablaufdatum"],"loesung":"- Option A: VM löschen und neu erstellen (Eval-ISO erneut verwenden)\\n  - Option B: `slmgr /rearm` (verlängert Eval um 180 Tage, max. 5 Mal)\\n  - Option C: Snapshot von \\"Clean-Install\\" wiederherstellen","praevention":"Regelmäßige Snapshots erstellen, Eval-Laufzeit im Kalender notieren\\n\\n**Quelle:** https://learn.microsoft.com/en-us/windows-server/get-started/evaluation (abgerufen 2026-10-19)\\n\\n---"},{"titel":"VM hat keinen Internetzugang","symptom":"VM kann keine Websites auflösen oder pingen","ursache":"Falscher Netzwerkadapter-Modus","diagnose_schritte":["`ipconfig` in der VM ausführen","Prüfe, ob eine IP-Adresse im NAT-Bereich (z. B. 192.168.x.x) vorhanden ist","Prüfe VMware-Einstellungen: VM → Settings → Network Adapter","Prüfe, ob \\"Connected\\" und \\"Connect at power on\\" aktiviert sind"],"loesung":"- Netzwerkadapter auf \\"NAT\\" stellen\\n  - VM neu starten\\n  - `ipconfig /release` und `ipconfig /renew` ausführen","praevention":"Netzwerkadapter-Einstellungen vor dem ersten Start prüfen\\n\\n---"},{"titel":"Windows 11 Home kann keine VMs mit Hyper-V","symptom":"Hyper-V-Option fehlt in Windows 11 Home","ursache":"Hyper-V ist nur in Pro/Enterprise/Education verfügbar","diagnose_schritte":["`winver` ausführen → Windows 11 Home bestätigt","\\"Windows-Features aktivieren oder deaktivieren\\" → Hyper-V nicht vorhanden"],"loesung":"VMware Workstation Pro verwenden (läuft auf Home, benötigt kein Hyper-V)","praevention":"VMware Workstation Pro als Hypervisor für Home-Benutzer empfehlen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was ist der Hauptgrund, warum Windows 11 Home für IT-Training nicht ausreicht?","optionen":["Es gibt keine Eingabeaufforderung","Hyper-V, GPO-Editor und RDP-Host fehlen","Windows 11 Home kann keine VMs ausführen","Es gibt keinen Geräte-Manager"],"antwort":1,"erklaerung":"Hyper-V, gpedit.msc und RDP-Host sind in Home nicht verfügbar."},{"nummer":2,"frage":"Wie lange ist die Evaluation-Laufzeit von Windows 11 Enterprise?","optionen":["30 Tage","90 Tage","180 Tage","365 Tage"],"antwort":2,"erklaerung":"180 Tage (verlängerbar mit `slmgr /rearm`)."},{"nummer":3,"frage":"Welcher Netzwerkmodi in VMware ermöglicht Internetzugang für die VM?","optionen":["Host-only","Internal","NAT","Isolated"],"antwort":2,"erklaerung":"NAT (Network Address Translation) teilt die Internetverbindung des Hosts."},{"nummer":4,"frage":"Was ist der wichtigste Vorteil von Snapshots in VMware?","optionen":["Sie beschleunigen die VM","Sie ermöglichen die exakte Wiederherstellung eines früheren Zustands","Sie sparen Festplattenplatz","Sie verbessern die Netzwerkgeschwindigkeit"],"antwort":1,"erklaerung":"Snapshots speichern den exakten Zustand der VM und ermöglichen die Wiederherstellung."},{"nummer":5,"frage":"Welches Tool verwenden wir für das Homelab auf Windows 11 Home?","optionen":["Hyper-V","VirtualBox","VMware Workstation Pro","Sandbox"],"antwort":2,"erklaerung":"VMware Workstation Pro (kostenlos, läuft auf Home, kein Hyper-V nötig)."}],"ticket":[{"situation":"Ein Kollege meldet: \\"Mein PC startet nicht mehr. Ich habe gestern ein Windows-Update installiert und seitdem erscheint nur noch ein blauer Bildschirm mit der Meldung \'INACCESSIBLE_BOOT_DEVICE\'.\\"","aufgabe":"1. Was ist die wahrscheinlichste Ursache?\\n2. Wie würdest du das Problem diagnostizieren?\\n3. Wie würdest du es lösen?\\n4. Wie würdest du verhindern, dass das Problem erneut auftritt?","loesung":"**1. Wahrscheinlichste Ursache:**\\nEin inkompatibler oder beschädigter Speichertreiber, der durch das Update installiert wurde. Der Boot-Vorgang schlägt fehl, weil Windows die Systempartition nicht mehr lesen kann.\\n\\n**2. Diagnose-Schritte:**\\n- In den Windows Recovery Environment (WinRE) booten (3x Unterbrechen beim Booten → \\"Erweiterte Optionen\\")\\n- \\"Problembehandlung\\" → \\"Erweiterte Optionen\\" → \\"Eingabeaufforderung\\"\\n- `chkdsk C: /f /r` ausführen (Festplattenfehler prüfen)\\n- `sfc /scannow /offbootdir=C:\\\\ /offwindir=C:\\\\Windows` ausführen (Systemdateien prüfen)\\n- `dism /image:C:\\\\ /cleanup-image /revertpendingactions` ausführen (Update rückgängig machen)\\n\\n**3. Lösung:**\\n- Option A: `dism /image:C:\\\\ /cleanup-image /revertpendingactions` — letztes Update rückgängig machen\\n- Option B: Systemwiederherstellung aus einem Wiederherstellungspunkt\\n- Option C: `bootrec /fixmbr`, `bootrec /fixboot`, `bootrec /rebuildbcd` — Boot-Sektor reparieren\\n- Option D: Letzte bekannte gute Konfiguration (F8 beim Start)\\n\\n**4. Prävention:**\\n- Vor Updates immer einen Wiederherstellungspunkt erstellen\\n- Treiber-Updates manuell prüfen (Hersteller-Website)\\n- Regelmäßige Backups (Datei-Historie oder Systemabbild)\\n- Im Homelab: Update in VM testen, bevor es auf dem echten System installiert wird\\n\\n---"}],"slug":"modul-0-homelab"},{"title":"Modul 1: Grundlagen — Rolle, Ticketsystem, Kommunikation, SLA, Eskelation","level":1,"module":1,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"},{"url":"https://www.ibm.com/think/topics/it-infrastructure-library","abrufdatum":"2026-10-19"},{"url":"https://www.coursera.org/learn/technical-support-fundamentals","abrufdatum":"2026-10-19"},{"url":"https://www.itil.org.uk/training/itil-foundation-level-courses/itil-foundation-training","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"SLA-Definitionen nicht eingehalten","symptom":"Beschwerden von Benutzern über lange Wartezeiten","ursache":"Keine klare SLA-Definition oder keine SLA-Überwachung","diagnose_schritte":["Prüfe, ob SLAs im Ticketsystem definiert sind","Analysiere die durchschnittliche Reaktions- und Lösungszeit der letzten 20 Tickets","Vergleiche mit den vereinbarten SLA-Werten"],"loesung":"- SLA-Regeln im Ticketsystem konfigurieren (automatische Eskalation bei Überschreitung)\\n  - Wöchentliches SLA-Reporting einführen\\n  - Team-Schulung zu SLA-Bedeutung","praevention":"SLAs bereits bei der Einführung des Ticketsystems definieren\\n\\n---"},{"titel":"Incident mit Problem verwechselt","symptom":"Dasselbe Problem tritt wiederholt auf","ursache":"Der Incident wurde gelöst (Workaround), aber das Problem nicht dokumentiert","diagnose_schritte":["Prüfe, ob es bereits ähnliche Incidents gab (Ticket-Historie durchsuchen)","Identifiziere die gemeinsame Ursache","Erstelle ein Problem-Ticket"],"loesung":"- Problem-Ticket mit allen referenzierten Incidents erstellen\\n  - Root-Cause-Analyse durchführen\\n  - Workaround dokumentieren","praevention":"Nach jedem Incident prüfen: \\"Ist das gelöst oder nur umgangen?\\"\\n\\n---"},{"titel":"Mangelnde Dokumentation","symptom":"Kollege kann übernommenes Ticket nicht bearbeiten","ursache":"Ticket wurde ohne ausreichende Notizen geschlossen","diagnose_schritte":["Öffne das betroffene Ticket","Prüfe, ob alle Schritte dokumentiert sind","Frage dich: \\"Könnte ein Kollege das Ticket ohne weitere Informationen bearbeiten?\\""],"loesung":"- Ticket mit detaillierten Notizen aktualisieren\\n  - Alle ausgeführten Schritte, Befunde und Ergebnisse dokumentieren","praevention":"Dokumentations-Checkliste verwenden:\\n  - [ ] Beschreibung des Problems\\n  - [ ] Diagnose-Schritte\\n  - [ ] Lösung/Workaround\\n  - [ ] Verifizierung (Problem gelöst?)\\n\\n---"},{"titel":"Unklare Eskalationsentscheidungen","symptom":"Ticket \\"hängt\\" niemand weiß, wer zuständig ist","ursache":"Kein klarer Eskalationspfad definiert","diagnose_schritte":["Prüfe, ob der Eskalationspfad im Ticketsystem definiert ist","Überprüfe, ob Eskalationsregeln eingehalten werden","Identifiziere, wer für welche Kategorie zuständig ist"],"loesung":"- Eskalationsmatrix erstellen (Kategorie → Level → Kontakt)\\n  - Automatische Eskalation konfigurieren\\n  - Team-Schulung durchführen","praevention":"Eskalationsmatrix bereits bei Systemeinführung erstellen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Welche Priorität hat ein kompletter Netzwerk-Ausfall im 1. Stock?","optionen":["P1","P2","P3","P4"],"antwort":0,"erklaerung":"Kritisch (P1), da ein kompletter Ausfall vorliegt."},{"nummer":2,"frage":"Was ist der Unterschied zwischen Incident und Problem?","optionen":["Ein Incident ist schlimmer als ein Problem","Ein Incident ist eine Unterbrechung, ein Problem ist die Ursache","Ein Problem ist eine Anfrage, ein Incident ist eine Störung","Es gibt keinen Unterschied"],"antwort":1,"erklaerung":"Incident = Symptom, Problem = Ursache."},{"nummer":3,"frage":"Was bedeutet SLA?","optionen":["System Level Agreement","Service Level Agreement","Support Level Agreement","Security Level Agreement"],"antwort":1,"erklaerung":"Service Level Agreement."},{"nummer":4,"frage":"Wann solltest du ein Ticket eskalieren?","optionen":["Bei jedem Problem","Nur wenn der Chef es sagt","Wenn es nicht in deiner Kompetenz liegt oder die SLA-Frist erreicht ist","Niemals"],"antwort":2,"erklaerung":"Eskalation bei Kompetenzgrenze oder SLA-Überschreitung."},{"nummer":5,"frage":"Was ist die wichtigste Regel bei der Benutzer-Kommunikation?","optionen":["Fachjargon verwenden","Aktiv zuhören und einfache Sprache verwenden","Schnelle Lösung versprechen","E-Mails sofort beantworten"],"antwort":1,"erklaerung":"Aktiv zuhören, einfache Sprache."}],"ticket":[{"situation":"Ein Mitarbeiter aus der Buchhaltung meldet sich: \\"Ich habe gestern mein Passwort geändert und seitdem funktioniert Outlook nicht mehr. Ich bekomme ständig eine Aufforderung, mein Passwort einzugeben, aber wenn ich es eingebe, erscheint wieder die Fehlermeldung. Ich muss dringend E-Mails beantworten.\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP2 (Hoch) — E-Mail ist betriebskritisch, aber es gibt einen Workaround (Web-Outlook).\\n\\n**2. Diagnose:**\\n- Prüfe, ob der Benutzer im Active Directory existiert und das korrekte Passwort hat\\n- Prüfe, ob das Passwort im AD korrekt gespeichert ist\\n- Prüfe, ob Outlook den Cached-Modus verwendet (das alte Passwort ist im Cache gespeichert)\\n- Prüfe, ob der Benutzer das Passwort in Windows aktualisiert hat (Credential Manager)\\n\\n**3. Lösung:**\\n- Credential Manager öffnen (Systemsteuerung → Benutzerkonten → Credential Manager)\\n- Gespeicherte Anmeldeinformationen für Outlook/Exchange finden und entfernen\\n- Outlook neu starten — es sollte nach dem neuen Passwort fragen\\n- Alternative: `control keymgr.dll` ausführen, um den Credential Manager direkt zu öffnen\\n\\n**4. Dokumentation:**\\n- Problem: Passwort-Change → Outlook fragt wiederholt nach Passwort\\n- Ursache: Altes Passwort im Windows Credential Manager gespeichert\\n- Lösung: Credential Manager → Windows-Anmeldeinformationen → Outlook-Eintrag entfernen\\n- Verifizierung: Outlook startet ohne Passwort-Aufforderung\\n\\n---"}],"slug":"modul-1-grundlagen"},{"title":"Modul 10: Boot- und Wiederherstellungsprobleme — WinRE, SFC, DISM, BitLocker-Recovery","level":2,"module":10,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/en-us/windows-hardware/manufacture/desktop/windows-recovery-environment--windows-re--technical-reference?view=windows-11","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/recovery-overview","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-hardware/manufacture/desktop/repair-a-windows-image?view=windows-11","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/answers/questions/2320913/using-system-file-checker-and-restoring-corrupted","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"SFC und DISM in falscher Reihenfolge","symptom":"SFC meldet „Windows Resource Protection found corrupt files but was unable to fix some of them\\" — DISM wird nicht ausgeführt","ursache":"Kenntnis der Abhängigkeit zwischen SFC und DISM fehlt","diagnose_schritte":["SFC-Logfile prüfen: `findstr /c:\\"[SR]\\" %windir%\\\\Logs\\\\CBS\\\\CBS.log > \\"%userprofile%\\\\Desktop\\\\sfcdetails.txt\\"`","Prüfen, ob SFC Dateien nicht reparieren konnte","Prüfen, ob der Komponenten-Store beschädigt ist: `Dism /Online /Cleanup-Image /CheckHealth`"],"loesung":"- DISM ausführen: `Dism /Online /Cleanup-Image /RestoreHealth`\\n  - Nach DISM-Schluss SFC erneut ausführen: `sfc /scannow`\\n  - SFC und DISM können mehrmals nacheinander ausgeführt werden, um alle Fehler zu beheben[Microsoft Learn — SFC, 2026-10-19]","praevention":"Immer zuerst SFC, dann DISM, dann SFC erneut — diese Reihenfolge ist am effektivsten\\n\\n---"},{"titel":"Falscher Laufwerksbuchstabe in WinRE","symptom":"SFC/DISM-Fehler „The system cannot find the path specified\\" — Windows-Laufwerk ist in WinRE nicht C:","ursache":"In WinRE kann das Windows-Laufwerk einen anderen Laufwerksbuchstaben haben (oft D: oder E:)","diagnose_schritte":["In WinRE-Eingabeaufforderung: `BCDEdit` ausführen","Unter „Windows Boot Loader\\" den Wert neben `osdevice` notieren","Alternativ: `diskpart` → `list volume` → Windows-Partition identifizieren → `exit`[Microsoft Learn — BitLocker, 2026-10-19][Microsoft Learn — Repair, 2026-10-19]","Prüfen mit: `dir C:\\\\Windows` oder `dir D:\\\\Windows`"],"loesung":"- SFC mit korrektem Laufwerk: `sfc /scannow /offbootdir=D:\\\\ /offwindir=D:\\\\Windows`\\n  - DISM mit korrektem Laufwerk: `Dism /Image:D:\\\\ /Cleanup-Image /RestoreHealth`[Microsoft Learn — BitLocker, 2026-10-19][Microsoft Learn — Repair, 2026-10-19]","praevention":"Immer vor SFC/DISM den Laufwerksbuchstaben mit `BCDEdit` oder `diskpart` prüfen\\n\\n---"},{"titel":"BitLocker-Recovery-Schlüssel verloren","symptom":"User meldet „BitLocker verlangt Recovery-Schlüssel, aber ich habe ihn nicht\\"","ursache":"Recovery-Schlüssel wurde nicht an einem sicheren Ort gespeichert oder die TPM-Konfiguration wurde geändert","diagnose_schritte":["Prüfen, ob der Schlüssel im Microsoft-Konto verfügbar ist: Benutzer auffordern, sich unter account.microsoft.com/devices/recoverykey anzumelden","In einer Domänen-Umgebung: AD-Objekt des Computers öffnen und Recovery-Schlüssel auslesen","Prüfen, ob ein Ausdruck oder eine Textdatei vorhanden ist"],"loesung":"- Wenn Schlüssel gefunden: in WinRE oder auf dem BitLocker-Bildschiff eingeben\\n  - Wenn Schlüssel nicht gefunden: Datenrettung durch spezialisierte Dienstleister (teilerfolg)\\n  - Letzter Ausweg: Windows zurücksetzen oder neu installieren (Datenverlust)[Microsoft Learn — Repair, 2026-10-19]","praevention":"BitLocker-Recovery-Schlüssel in Active Directory sichern und/oder im Microsoft-Konto speichern; Benutzer instruieren, den Schlüssel auszudrucken\\n\\n---"},{"titel":"Boot-Schleife — Startup Repair meldet „Couldn\'t repair your PC","symptom":"PC startet wiederholt neu, Startup Repair schlägt fehl, System Restore ist nicht verfügbar","ursache":"Systemdateien oder BCD (Boot Configuration Data) sind stark beschädigt","diagnose_schritte":["WinRE öffnen: Eingabeaufforderung","BCD reparieren: `bootrec /fixmbr`, `bootrec /fixboot`, `bootrec /rebuildbcd`[CompTIA A+, 2026-10-19]","Partitionstyp prüfen: `diskpart` → `list disk` → `select disk 0` → `list partition`","Prüfen, ob EFI-Partition vorhanden und aktiv ist"],"loesung":"- BCDStore neu erstellen: `bootrec /rebuildbcd`\\n  - Wenn fehlgeschlagen: BCD manuell neu erstellen mit `bcdedit`\\n  - Als letzte Option: Neuinstallation mit „Benutzerdefinierte Installation\\" (Dateien behalten, wenn möglich)[CompTIA A+, 2026-10-19]","praevention":"Regelmäßige Systemimages erstellen; Windows Updates nicht abbrechen; SSD/Gesundheit der Festplatte überwachen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Wie lautet der Befehl, um SFC offline auf ein nicht startendes Windows-System anzuwenden?","optionen":["`sfc /scannow`","`sfc /scannow /offbootdir=D:\\\\ /offwindir=D:\\\\Windows`","`sfc /offline D:\\\\Windows`","`sfc /repair D:\\\\`"],"antwort":1,"erklaerung":"SFC benötigt die Parameter `/offbootdir` und `/offwindir` für die Offline-Nutzung."},{"nummer":2,"frage":"Welches Tool repariert den Komponenten-Store (WinSxS), von dem SFC abhängig ist?","optionen":["chkdsk","bootrec","DISM","manage-bde"],"antwort":2,"erklaerung":"DISM (Deployment Image Servicing and Management) repariert den Komponenten-Store."},{"nummer":3,"frage":"Was tun, wenn SFC meldet, dass es Dateien nicht reparieren konnte?","optionen":["Den PC neu starten und SFC erneut ausführen","DISM ausführen und anschließend SFC erneut ausführen","Windows neu installieren","Den Fehler ignorieren"],"antwort":1,"erklaerung":"DISM repariert den Komponenten-Store, dann kann SFC die Systemdateien reparieren."},{"nummer":4,"frage":"Wie lang ist ein BitLocker-Recovery-Schlüssel?","optionen":["16 Zeichen","24 Zeichen","48 Ziffern","64 Zeichen"],"antwort":2,"erklaerung":"Der BitLocker-Recovery-Schlüssel besteht aus 48 Ziffern."},{"nummer":5,"frage":"Was ist der erste Schritt bei der Boot-Reparatur, wenn Windows nicht startet?","optionen":["Windows neu installieren","WinRE öffnen und Startup Repair ausführen","Die Festplatte formatieren","Die BIOS-Einstellungen zurücksetzen"],"antwort":1,"erklaerung":"WinRE → Startup Repair ist der erste Schritt, bevor manuelle Reparaturen durchführt."}],"ticket":[{"situation":"Ein Mitarbeiter aus der Buchhaltung meldet sich: „Ich habe gestern ein Windows-Update installiert und seitdem startet Windows nicht mehr. Der Bildschirm zeigt \'Preparing Automatic Repair\', dann geht alles wieder von vorne. Ich komme nicht auf meinen Desktop und habe dringend Dateien auf dem Laptop. Der Laptop ist mit BitLocker verschlüsselt.\\"","aufgabe":"1. Wie gehst du bei der Diagnose vor?\\n2. Wie löst du das Problem?\\n3. Wie stellst du sicher, dass die Daten erhalten bleiben?","loesung":"**1. Diagnose:**\\n- Prüfe, ob WinRE erreichbar ist: Power-Button 2–3× gedrückt halten, bis WinRE erscheint\\n- Navigiere zu **Problembehandlung > Erweiterte Optionen > Eingabeaufforderung**\\n- Prüfe den Laufwerksbuchstaben: `BCDEdit` — notiere den Wert neben `osdevice`\\n- Prüfe den BitLocker-Status: `manage-bde -status C:`\\n\\n**2. Lösung:**\\n- Wenn BitLocker aktiv: Entsperren mit Recovery-Schlüssel (vom Microsoft-Konto oder AD)\\n- Startup Repair versuchen: **Problembehandlung > Erweiterte Optionen > Startup Repair**\\n- Wenn fehlgeschlagen: System Restore zu einem früheren Wiederherstellungspunkt\\n- Wenn fehlgeschlagen: SFC offline: `sfc /scannow /offbootdir=C:\\\\ /offwindir=C:\\\\Windows`\\n- Wenn fehlgeschlagen: DISM offline: `Dism /Image:C:\\\\ /Cleanup-Image /RestoreHealth`, dann SFC erneut\\n\\n**3. Daten-Erhalt:**\\n- Vor jeder Maßnahme: Daten mit `robocopy` oder über WinRE-Eingabeaufforderung auf einen USB-Stick kopieren\\n- Wenn Windows nicht repariert werden kann: Neuinstallation mit „Benutzerdefinierte Installation\\" und Option „Dateien behalten\\" (wenn verfügbar)\\n- Wenn die Partition beschädigt ist: Datenrettungstools (z. B. TestDisk) in WinRE nutzen\\n\\n**4. Dokumentation:**\\n- Problem: Boot-Schleife nach Windows-Update\\n- Diagnose: WinRE erreichbar, BitLocker aktiv, Laufwerk C:\\n- Lösung: DISM + SFC offline, System Restore\\n- Verifizierung: Windows startet normal\\n\\n---"}],"slug":"modul-10-boot-recovery"},{"title":"Modul 11: Active Directory, Gruppenrichtlinien, Benutzer- und Rechteverwaltung","level":2,"module":11,"last_verified":"2026-10-19","windows_version":"Windows Server 2022","sources":[{"url":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-overview","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-management-console","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows-server/identity/ad-ds/manage/group-policy/group-policy-processing","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows-server/identity/ad-ds/plan/delegating-administration-by-using-ou-objects","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows-server/identity/ad-ds/manage/delegation-control-wizard","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows-server/identity/ad-ds/plan/creating-an-organizational-unit-design","abrufdatum":"2026-10-19"},{"url":"https://www.professormesser.com/free-a-plus-training/220-1102/220-1102-video/active-directory-220-1102/","abrufdatum":"2026-10-19"},{"url":"https://courseiva.com/learn/a-plus-core-2/windows-group-policy","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"GPO wird nicht angewendet — Link an falscher Stelle","symptom":"Die GPO-Einstellungen erscheinen auf dem Client nicht","ursache":"Die GPO wurde nicht mit der richtigen OU oder Domäne verknüpft","diagnose_schritte":["Öffne die GPMC und prüfe, ob die GPO mit der gewünschten OU verknüpft ist","Prüfe, ob der GPO-Link aktiviert ist (Link Enabled)","Prüfe mit `gpresult /r` auf dem Client, ob die GPO in der Liste der angewendeten GPOs erscheint","Prüfe, ob die richtigen Sicherheitsberechtigungen auf der GPO vorhanden sind"],"loesung":"- GPO-Link mit der richtigen OU verknüpfen (Rechtsklick auf OU → „Vorh. GPO verknüpfen\\")\\n  - Berechtigungen prüfen: Die Benutzer/Gruppe muss über „Lesen\\" und „Gruppenrichtlinie anwenden\\" verfügen","praevention":"GPO-Verknüpfungen immer in der GPMC überprüfen, nicht nur den Link erstellen\\n\\n---"},{"titel":"Block Inheritance verhindert kritische Sicherheits-GPOs","symptom":"Eine auf Domänenebene konfigurierte Sicherheits-GPO wird auf bestimmte OUs nicht angewendet","ursache":"Auf der OU wurde „Vererbung blockieren\\" aktiviert","diagnose_schritte":["Öffne die GPMC und prüfe die betroffene OU — erscheint ein blauer Ausrufezeichen?","Prüfe die GPO-Links auf der OU — welche sind aktiv?","Identifiziere die GPOs, die durch Block Inheritance blockiert werden"],"loesung":"- Block Inheritance deaktivieren (Rechtsklick auf OU → „Vererbung blockieren\\" deaktivieren)\\n  - Alternativ: Die kritische GPO als **Enforced** markieren — Enforced überschreibt Block Inheritance","praevention":"Block Inheritance nur in Ausnahmefällen verwenden; kritische Sicherheits-GPOs sollten als Enforced markiert werden\\n\\n---"},{"titel":"Delegierte Rechte funktionieren nicht — falsche Berechtigungsebene","symptom":"Ein Helpdesk-Mitarbeiter kann trotz Delegierung keine Passwörter zurücksetzen","ursache":"Die Delegierung wurde auf der falschen OU oder mit falschen Aufgaben durchgeführt","diagnose_schritte":["Prüfe in ADUC: Welche OU wurde delegiert? Enthält sie die betroffenen Benutzerobjekte?","Prüfe im Delegation of Control-Assistenten: Welche Aufgabe wurde delegiert?","Prüfe die Berechtigungen: ADUC → Ansicht → Erweiterte Funktionen → Eigenschaften der OU → Sicherheit → Erweitert","Vergewissere dich, dass die Gruppe über „Kennwort zurücksetzen\\" für die gewünschten Objekte verfügt"],"loesung":"- Delegierung auf der OU durchführen, die tatsächlich die Benutzer enthält\\n  - Im Assistenten die korrekte Aufgabe auswählen: „Benutzerkennwörter zurücksetzen und die Kennwortänderung bei der nächsten Anmeldung erzwingen\\"\\n  - Alternativ: Benutzer oder Gruppe zu einer Gruppe mit den entsprechenden Berechtigungen hinzufügen","praevention":"Delegierungen dokumentieren und regelmäßig überprüfen; Testen mit einem Testkonto vor der Produktivschaltung\\n\\n---"},{"titel":"GPO-Änderungen werden erst nach Neustart angewendet","symptom":"Änderungen an einer GPO werden erst nach einem Neustart des Clients oder einer erneuten Anmeldung des Benutzers wirksam","ursache":"Die GPO wurde nicht aktualisiert","diagnose_schritte":["Prüfe, ob der Client die Domäne erreicht (Domänenmitgliedschaft)","Führe `gpupdate /force` aus, um die sofortige Aktualisierung zu erzwingen","Prüfe mit `gpresult /r`, ob die GPO-Liste aktuell ist","Prüfe, ob der Client SYSVOL korrekt erreicht (Netzwerkverbindung zum DC)"],"loesung":"- `gpupdate /force` ausführen (erzwingt die Aktualisierung aller GPOs)\\n  - Bei Computer-Konfigurationen: Neustart ist oft erforderlich\\n  - Bei Benutzer-Konfigurationen: Ab- und erneutes Anmeldung reicht in der Regel","praevention":"GPO-Änderungen planen und nach der Änderung `gpupdate /force` auf den betroffenen Clients ausführen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"In welcher Reihenfolge werden GPOs verarbeitet (LSDOU)?","optionen":["Local → Site → Domain → OU","Site → Domain → OU → Local","OU → Domain → Site → Local","Domain → Site → OU → Local"],"antwort":0,"erklaerung":"Local, Site, Domain, Organizational Unit."},{"nummer":2,"frage":"Was passiert, wenn Block Inheritance auf einer OU aktiviert ist?","optionen":["Alle GPOs werden angewendet","Die OU erbt keine GPOs von übergeordneten Containern, außer sie sind als Enforced markiert","Die OU erbt nur lokale GPOs","Block Inheritance deaktiviert alle GPOs"],"antwort":1,"erklaerung":"Block Inheritance verhindert die Vererbung, außer die GPO ist Enforced."},{"nummer":3,"frage":"Welches Tool wird primär zur Delegierung von Verwaltungsrechten verwendet?","optionen":["gpedit.msc","Der Delegation of Control-Assistent in ADUC","regedit.exe","services.msc"],"antwort":1,"erklaerung":"Der Delegation of Control-Assistent in „Active Directory-Benutzer und -Computer\\"."},{"nummer":4,"frage":"Wo wird der Group Policy Template (GPT) gespeichert?","optionen":["Nur im Active Directory","Im SYSVOL-Ordner auf jedem Domain Controller","Nur auf dem lokalen Client","In der Registry des Domain Controllers"],"antwort":1,"erklaerung":"Der GPT liegt im SYSVOL-Ordner auf jedem Domain Controller unter `\\\\\\\\<Domäne>\\\\SYSVOL\\\\<Domäne>\\\\Policies\\\\<GPO-GUID>\\\\`."},{"nummer":5,"frage":"Welches Kommando erzwingt die sofortige Aktualisierung aller Gruppenrichtlinien auf dem Client?","optionen":["gpresult /r","gpupdate /force","gpedit.msc","netstat /gp"],"antwort":1,"erklaerung":"`gpupdate /force`."}],"ticket":[{"situation":"Ein Mitarbeiter aus der Buchhaltung meldet sich: „Seit gestern kann ich mich nicht mehr anmelden. Ich bekomme die Fehlermeldung: „Das Konto ist gesperrt\\". Ich muss dringend auf die Buchhaltungsdaten zugreifen, da heute Monatsabschluss ist.\\"","aufgabe":"1. Analysiere beide Tickets und ordne sie nach Priorität zu\\n2. Beschreibe die Diagnose-Schritte für das gesperrte Konto\\n3. Beschreibe, wie du die Delegierung nutzen würdest, um das Passwort zurückzusetzen, ohne Domain-Admin-Rechte zu verwenden\\n4. Untersuche die GPO-Problematik: Welche GPO könnte den Desktop-Hintergrund verändert haben?\\n5. Dokumentiere den Fall für die Wissensdatenbank","loesung":"**1. Priorisierung:**\\n\\n| Ticket | Priorität | Begründung |\\n|--------|-----------|------------|\\n| Gesperrtes Konto (Buchhaltung) | P2 | Einzelner Benutzer betroffen, aber betriebskritisch (Monatsabschluss), Workaround: Administrator kann Konto entsperren |\\n| Desktop-Hintergrund (Vertrieb) | P4 | Kosmetischer Ärger, keine Auswirkungen auf die Arbeit |\\n\\n**2. Diagnose für gesperrtes Konto:**\\n\\n- ADUC öffnen und den Benutzer suchen\\n- Prüfen, ob das Konto gesperrt ist (Konto-Eigenschaften → „Konto ist gesperrt\\")\\n- Prüfen, ob das Konto deaktiviert ist\\n- Prüfen, ob der Benutzer das Passwort zu oft falsch eingegeben hat (Kontosperrungsrichtlinie)\\n- Prüfen, ob der Benutzer die maximale Kontogültigkeit erreicht hat\\n\\n**3. Delegierung für Passwort-Reset:**\\n\\n- Statt dem Helpdesk volle Domain-Admin-Rechte zu geben, wird eine Gruppe `Helpdesk-Team` erstellt\\n- Auf OU=Benutzer wird die Aufgabe „Benutzernamenswörter zurücksetzen\\" an diese Gruppe delegiert\\n- Das Helpdesk kann nun Passwörter zurücksetzen, ohne administrative Rechte auf dem Server zu benötigen\\n- Dokumentation der Delegierung: Datum, Aufgabe, Ziel-OU, berechtigte Gruppe\\n\\n**4. GPO-Analyse für Desktop-Hintergrund:**\\n\\n- GPMC öffnen und nach GPOs suchen, die mit OU=Vertrieb verknüpft sind\\n- Prüfen, ob eine GPO die Einstellung „Desktop-Hintergrund\\" unter `Benutzerkonfiguration > Richtlinien > Administrative Vorlagen > Desktop` konfiguriert hat\\n- Falls ja: Entweder den Benutzern die entsprechende Gruppe entziehen oder die GPO-Einstellung ändern\\n- Alternativ: Prüfen, ob eine neue GPO erstellt wurde, die die alte überschreibt (Letzte angewendet = gewinnt)\\n\\n**5. Dokumentation:**\\n\\n- **Problem 1:** Konto gesperrt (Buchhaltung) → Ursache: zu viele falsche Passworteingaben → Lösung: Konto in ADUC entsperren, Passwort zurücksetzen\\n- **Problem 2:** Desktop-Hintergrund geändert → Ursache: GPO „Desktop-Richtlinie Vertrieb\\" → Lösung: GPO-Einstellung anpassen oder für den Benutzer deaktivieren\\n- **Prävention:** Regelmäßige Überprüfung der Delegationen; GPO-Änderungen dokumentieren\\n\\n---"}],"slug":"modul-11-ad-gpo"},{"title":"Modul 12: Netzwerk Tiefe — VLAN, VPN, Firewall, DNS-Fehleranalyse","level":2,"module":12,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.professormesser.com/free-a-plus-training/220-1101/220-1101-video/vlans-and-vpns-220-1101/","abrufdatum":"2026-10-19"},{"url":"https://www.netacad.com/content/srwe/1.0/courses/content/m3/en-US/assets/3.4.6-lab---configure-vlans-and-trunking.pdf","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/manage-defender-windows-client/5-manage-windows-defender-firewall","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-server/networking/dns/troubleshoot/troubleshoot-dns-client","abrufdatum":"2026-10-19"},{"url":"https://blog.alphaprep.net/comptia-a-core-1-networking-tools-how-to-choose-the-right-tool-for-the-right-scenario/","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Falsche DNS-Server-Einstellung","symptom":"Der Benutzer kann Webseiten nicht aufrufen (Name nicht auflösbar), aber `ping 8.8.8.8` funktioniert","ursache":"Falsche oder nicht erreichbare DNS-Server in den Netzwerkeinstellungen","diagnose_schritte":["`ipconfig /all` — prüfe, welche DNS-Server konfiguriert sind","`ping <DNS-Server-IP>` — ist der DNS-Server erreichbar?","`nslookup www.example.com 8.8.8.8` — funktioniert DNS mit alternativ-Server?"],"loesung":"- DNS-Server in den Netzwerkeinstellungen (Systemsteuerung → Netzwerk → Adapter-Eigenschaften → IPv4) auf 8.8.8.8 und 8.8.4.4 (Google DNS) setzen\\n  - Falls im Unternehmensnetzwerk: Domänen-DNS-Server vom Administrator erfragen\\n  - `ipconfig /flushdns` ausführen","praevention":"DNS-Server-Einstellungen bei jedem Netzwerkwechsel prüfen\\n\\n---"},{"titel":"Firewall blockiert legitimen Datenverkehr","symptom":"Eine Anwendung (z. B. RDP, Drucker, Datenbank) kann nicht auf den Server zugreifen — die Firewall blockiert die Verbindung","ursache":"Keine Firewall-Regel für den benötigten Port oder die Anwendung","diagnose_schritte":["`ping <Server-IP>` — funktioniert die IP-Ebene?","`telnet <Server-IP> <Port>` oder `Test-NetConnection` — ist der Port erreichbar?","Windows Defender Firewall → Erweiterte Einstellungen → Eingehende Regeln prüfen","Prüfen, ob Block-Regel für den Port existiert"],"loesung":"- Systemsteuerung → Windows Defender Firewall → App oder Feature durch Firewall zulassen → Anwendung hinzufügen\\n  - Oder: Erweiterte Einstellungen → Eingehende Regel → Neue Regel → Port → TCP/UDP + Portnummer → Verbindung zulassen\\n  - Im Unternehmensnetzwerk: Firewall-Regel vom Netzwerkadministrator anfordern","praevention":"Firewall-Regeln dokumentieren und bei Neueinstellungen der Applications prüfen\\n\\n---"},{"titel":"VLAN-Fehlerkonfiguration","symptom":"Gerät im Netzwerk ist mit dem Switch verbunden, erhält keine IP-Adresse oder kann nicht mit anderen Geräten kommunizieren","ursache":"Switch-Port ist dem falschen VLAN zugeordnet (z. B. Port ist im VLAN 10, Gerät sollte im VLAN 20 sein)","diagnose_schritte":["Physikalische Verbindung prüfen (Link-LED am Switch-Port?)","`ipconfig` — erhält das Gerät eine IP-Adresse? (169.254.x.x = APIPA = kein DHCP)","Switch-Konfiguration prüfen: `show vlan brief` (Cisco IOS)","Prüfen, ob der Port als Access-Port konfiguriert und dem richtigen VLAN zugeordnet ist"],"loesung":"```\\n  Switch(config)# interface f0/6\\n  Switch(config-if)# switchport mode access\\n  Switch(config-if)# switchport access vlan 20\\n  Switch(config-if)# end\\n  Switch# show vlan brief\\n  ```","praevention":"VLAN-Konfiguration und Port-Zuordnungen dokumentieren\\n\\n---"},{"titel":"Veralteter DNS-Cache","symptom":"Webseite wurde auf neue IP umgezogen, aber der PC zeigt weiterhin Fehler oder alte Seite","ursache":"Der lokale DNS-Resolver-Cache enthält veralteten Eintrag","diagnose_schritte":["`ipconfig /displaydns` — suche nach dem Domain-Namen, prüfe die IP-Adresse","Vergleiche mit der aktuellen IP (z. B. über `nslookup www.example.com 8.8.8.8`)","Falls abweichend: Cache leeren"],"loesung":"```\\n  ipconfig /flushdns\\n  ```\\n  Danach den Browser-Cache leeren oder im Inkognito-Modus testen.","praevention":"Nach DNS-Änderungen immer `ipconfig /flushdns` ausführen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Welcher Switch-Port-Modus wird verwendet, um einen Port einem einzelnen VLAN zuzuordnen?","optionen":["Trunk-Modus","Access-Modus","Hybrid-Modus","Routing-Modus"],"antwort":1,"erklaerung":"Access-Modus. Ein Transport-Port wird einem einzelnen VLAN zugeordnet und verbindet Endgeräte."},{"nummer":2,"frage":"Welcher VPN-Typ wird typischerweise für die Verbindung einer Zweigstelle mit dem Hauptquartier verwendet?","optionen":["Remote-Access-VPN","SSL-VPN","Site-to-Site-VPN","Client-VPN"],"antwort":2,"erklaerung":"Site-to-Site-VPN. Es verbindet zwei Netzwerke permanent und transparent für Benutzer."},{"nummer":3,"frage":"Welcher Befehl leert den DNS-Resolver-Cache in Windows?","optionen":["`ipconfig /release`","`ipconfig /flushdns`","`nslookup /clear`","`ping /flush`"],"antwort":1,"erklaerung":"`ipconfig /flushdns` entfernt alle zwischengespeicherten DNS-Einträge."},{"nummer":4,"frage":"Sie können eine Webseite nicht über den Domain-Namen aufrufen, aber `ping 8.8.8.8` funktioniert. Was ist die wahrscheinlichste Ursache?","optionen":["Die Firewall blockiert den Browser","Der DNS-Server ist falsch konfiguriert","Der Switch ist defekt","Das Kabel ist nicht eingesteckt"],"antwort":1,"erklaerung":"Die IP-Verbindung funktioniert, die Namensauflösung schlägt fehl → DNS-Problem."},{"nummer":5,"frage":"Welches Windows-Firewall-Profil ist für ein öffentliches Netzwerk (z. B. Café) vorgesehen?","optionen":["Domain","Private","Public","Enterprise"],"antwort":2,"erklaerung":"Public. Das Public-Profil gilt für nicht vertrauenswürdige Netzwerke und hat die strengsten Firewall-Regeln."}],"ticket":[{"situation":"Ein Mitarbeiter im Homeoffice meldet sich: \\"Ich kann seit gestern auf keine unserer internen Server zugreifen. Ich VPN mich mit Cisco AnyConnect ein, aber wenn ich den Namen des Servers eingebe, kommt sofort \'Server nicht gefunden\'. Unsere Webseite www.unternehmen.de im Browser geht auch nicht.\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Welche Diagnose-Schritte führst du durch?\\n3. Welche Befehle verwendest du?\\n4. Wie dokumentierst du den Fall?","loesung":"**1. Priorität:**\\n\\nP2 (Hoch) — Der Mitarbeiter kann nicht arbeiten, aber es betrifft nur eine Person. P1 wäre ein kompletter Ausfall.\\n\\n**2. Diagnose-Schritte:**\\n\\n1. VPN-Verbindung prüfen: Ist das AnyConnect-VPN verbunden? (Icon in der Taskleiste)\\n2. IP-Adresse prüfen: `ipconfig /all` — erhält das Gerät eine IP aus dem VPN-Subnetz?\\n3. Gateway prüfen: `ping <VPN-Gateway>`\\n4. DNS-Server prüfen: Sind die internen DNS-Server in `ipconfig /all` sichtbar?\\n5. Namensauflösung testen: `nslookup <Server-Name>` — funktioniert die DNS-Abfrage?\\n6. `ipconfig /flushdns` ausführen\\n\\n**3. Mögliche Ursache und Lösung:**\\n\\n- **Ursache:** Der DNS-Server wurde im VPN-Tunnel nicht korrekt übernommen oder der lokale DNS-Cache ist veraltet\\n- **Lösung 1:** `ipconfig /flushdns` ausführen\\n- **Lösung 2:** VPN trennen und neu verbinden\\n- **Lösung 3:** Falls das Problem weiterhin besteht: DNS-Server manuell in den VPN-Adapter-Einträgen prüfen\\n- **Lösung 4:** Alternat DNS-Server testen: `nslookup <Server> <interne-DNS-IP>`\\n\\n**4. Dokumentation:**\\n\\n| Feld | Eintrag |\\n|------|---------|\\n| Problem | Kein Zugriff auf interne Server und Webseite nach VPN-Verbindung |\\n| Ursache | DNS-Einträge im VPN-Adapter nicht aktualisiert / veralteter DNS-Cache |\\n| Lösung | `ipconfig /flushdns` und VPN neu verbunden |\\n| Verifizierung | `nslookup <Server>` zeigt korrekte IP; Server ist erreichbar |\\n| Prävention | VPN-Client automatische DNS-Übernahme konfigurieren |\\n\\n---"}],"slug":"modul-12-netzwerk-tiefe"},{"title":"Modul 13: PowerShell für Support-Automatisierung","level":2,"module":13,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/de-de/powershell/scripting/overview","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/powershell/scripting/learn/ps101/00-introduction","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/powershell/module/microsoft.powershell.management/get-process","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/content/guides/comptia-a-plus-certification","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"PowerShell-Skript wird nicht ausgeführt","symptom":"Fehlermeldung „Das Ausführen von Skripten ist auf diesem System deaktiviert\\"","ursache":"Die Execution Policy (Ausführungsrichtlinie) blockiert die Skriptausführung","diagnose_schritte":["`Get-ExecutionPolicy` ausführen — zeigt die aktuelle Richtlinie","Prüfen, ob die Richtlinie `Restricted` ist","Den Scope prüfen: `Get-ExecutionPolicy -List`"],"loesung":"- `Set-ExecutionPolicy -ExecutionPolicy RemoteSigned -Scope CurrentUser` ausführen\\n  - Danach sollte `Get-ExecutionPolicy` den Wert `RemoteSigned` zurückgeben","praevention":"Execution Policy bei der Einrichtung der Testumgebung korrekt konfigurieren\\n\\n---"},{"titel":"Cmdlet wird nicht erkannt","symptom":"Fehlermeldung „Der Begriff \'Get-Process\' wird nicht als Name eines Cmdlets erkannt\\"","ursache":"falsche Modul-Pfad oder nicht importiertes Modul","diagnose_schritte":["Prüfen, ob das Modul vorhanden ist: `Get-Module -ListAvailable`","Prüfen, ob das Modul geladen ist: `Get-Module`","Ggf. Modul manuell importieren: `Import-Module Microsoft.PowerShell.Management`"],"loesung":"- Modul-Pfad überprüfen und ggf. PATH-Umgebungsvariable korrigieren\\n  - In PowerShell 7: `Get-Module -ListAvailable` nutzen, um verfügbare Module zu finden","praevention":"Module beim Anmelden automatisch laden (Profile-Skript in `$PROFILE`)\\n\\n---"},{"titel":"Pipeline-Fehler bei fehlenden Eigenschaften","symptom":"Leere Ausgabe oder Fehlermeldung beim Verketten von Befehlen","ursache":"Eigenschaft existiert nicht oder ist `$null`; falsche Objektstruktur","diagnose_schritte":["Objekttyp prüfen: `Get-Process | Get-Member`","Verfügbare Eigenschaften anzeigen: `(Get-Process -Name \\"powershell\\").PSObject.Properties.Name`","Prüfen, ob Eigenschaften NULL sind: `Get-Process | Select-Object Name, Id, WorkingSet`"],"loesung":"- `Select-Object` nutzen, um benötigte Eigenschaften auszuwählen\\n  - `Where-Object` mit korrekten Eigenschaftsnamen verwenden\\n  - Bei `$null`-Werten: `if ($null -ne $variable)` prüfen","praevention":"Vor der Pipeline die Struktur des Objekts mit `Get-Member` prüfen\\n\\n---"},{"titel":"Zugriffsverweigert bei Remote-Befehlen","symptom":"Fehlermeldung „Zugriff verweigert\\" bei `Invoke-Command` oder `Enter-PSSession`","ursache":"PowerShell Remoting nicht aktiviert oder fehlende Administratorrechte auf Zielcomputer","diagnose_schritte":["Prüfen, ob Remoting aktiviert: `Test-WSMan -ComputerName \\"PC-02\\"`","Prüfen, ob der aktuelle Benutzer Administrator auf dem Zielcomputer ist","Windows-Firewall-Regeln für WinRM prüfen"],"loesung":"- Auf dem Zielcomputer: `Enable-PSRemoting -Force` ausführen (als Administrator)\\n  - Windows-Dienste `WinRM` starten: `Start-Service WinRM`\\n  - Firewall-Ausnahme für WinRM überprüfen","praevention":"Remoting bei der Systemeinrichtung aktivieren und dokumentieren\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was bedeutet die Pipeline `|` in PowerShell?","optionen":["Sie trennt Befehle voneinander","Sie leitet die Ausgabe eines Befehls als Eingabe an den nächsten Befehl weiter","Sie beendet einen Befehl","Sie erstellt eine neue Datei"],"antwort":1,"erklaerung":"Die Pipeline leitet Objekte vom ersten zum nächsten Befehl weiter."},{"nummer":2,"frage":"Welches Cmdlet zeigt alle laufenden Prozesse an?","optionen":["`Get-Process`","`Show-Process`","`List-Process`","`Display-Process`"],"antwort":0,"erklaerung":"`Get-Process` ist das Standard-Cmdlet zur Anzeige laufender Prozesse."},{"nummer":3,"frage":"Wie nennt man die Grundstruktur eines PowerShell-Befehls?","optionen":["`Verb-Noun`","`Substantiv-Verb`","`Befehl-Option`","`Get-Set`"],"antwort":0,"erklaerung":"PowerShell-Cmdlets folgen dem Muster `Verb-Noun` (z. B. `Get-Service`)."},{"nummer":4,"frage":"Was passiert, wenn du ein Skript mit `.\\\\skript.ps1` startest und die Execution Policy ist `Restricted`?","optionen":["Das Skript wird ohne Warnung ausgeführt","Das Skript wird nicht ausgeführt und eine Fehlermeldung erscheint","Windows Installiert das Skript automatisch","Der Computer wird neu gestartet"],"antwort":1,"erklaerung":"Die Execution Policy `Restricted` verhindert die Skriptausführung."},{"nummer":5,"frage":"Welches Cmdlet liest die Windows-Ereignisanzeige aus?","optionen":["`Get-EventLog`","`Read-Event`","`Show-Event`","`Get-Log`"],"antwort":0,"erklaerung":"`Get-EventLog` liest Einträge aus den Windows-Ereignisprotokollen."}],"ticket":[{"situation":"Ein Mitarbeiter meldet: \\"Mein PC ist seit gestern extrem langsam. Ich habe viele Programme offen, aber das Problem trat auch nach einem Neustart auf. Ich arbeite dringend an einer Präsentation für heute.\\"","aufgabe":"1. Erstelle einen Diagnose-Befehl mit PowerShell, der die CPU- und Speicherauslastung aktueller Prozesse anzeigt\\n2. Identifiziere mögliche Ursache für die langsame Leistung\\n3. Dokumentiere deine Befehle und Ergebnisse für den Fallbericht","loesung":"**1. Diagnose-Befehl:**\\n\\n```powershell\\n# Top-10-Prozesse nach CPU-Zeit\\nGet-Process | Sort-Object CPU -Descending | Select-Object -First 10 Name, Id, CPU, WorkingSet\\n\\n# Top-10-Prozesse nach Speicherbedarf\\nGet-Process | Sort-Object WorkingSet -Descending | Select-Object -First 10 Name, Id, WorkingSet\\n```\\n\\n**2. Mögliche Ursache:**\\n- Ein Prozess verbraucht übermäßig viele Ressourcen (CPU oder Speicher)\\n- Mögliche Ursachen: defekter Treiber, böswillige Software, zu viele Hintergrundprozesse\\n\\n**3. Dokumentation:**\\n- Befehl: `Get-Process | Sort-Object CPU -Descending | Select-Object -First 10 Name, Id, CPU, WorkingSet`\\n- Ergebnis: Prozess „chrome.exe\\" verbraucht 45% CPU und 1,2 GB Speicher\\n- Massnahme: Prozess beenden (`Stop-Process -Id 1234`) und ggf. Virenscan durchführen\\n\\n---"}],"slug":"modul-13-powershell"},{"title":"Modul 14: Software-Deployment, Intune/Entra ID Grundlagen","level":2,"module":14,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/en-us/intune/fundamentals/what-is-intune","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/entra/fundamentals/whatis","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/intune/intune-service/apps/apps-windows-10-app-deploy","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/manage-roles-portal","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/intro-to-endpoint-manager/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/manage-devices-with-microsoft-endpoint-manager/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/add-application-portal-setup-sso","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Gerät wird nicht automatisch in Intune registriert","symptom":"Gerät ist mit Entra ID verbunden, erscheint aber nicht in Intune","ursache":"Automatische MDM-Registrierung ist nicht konfiguriert oder die Intune-Lizenz fehlt","diagnose_schritte":["Prüfe, ob eine Intune-Lizenz für den Benutzer oder das Gerät zugewiesen ist","Prüfe unter Entra ID → Mobility (MDM und MAM) → Microsoft Intune die MDM-Benutzereinstellung","Prüfe, ob die automatische Registrierung konfiguriert ist"],"loesung":"1. Intune-Lizenz für den Benutzer zuweisen\\n  2. Unter Entra ID → Mobility (MDM und MAM) die automatische Registrierung aktivieren\\n  3. Alternative: Benutzer registriert Gerät manuell über die Company Portal-App","praevention":"Automatische Registrierung bei allen neuen Geräten von Anfang an konfigurieren\\n\\n---"},{"titel":"App-Installation schlägt fehl, obwohl App zugewiesen ist","symptom":"Benutzer sieht App im Company Portal, Installation schlägt aber fehl","ursache":"Falscher Installationsbefehl oder fehlende Erkennungsregel","diagnose_schritte":["Prüfe den Installationsbefehl in der Intune-App-Konfiguration","Prüfe, ob die App auf dem Gerät bereits installiert ist (Evtl. wurde eine vorherige Installation nicht erkannt)","Prüfe das Intune-Protokoll unter dem Gerät in Intune"],"loesung":"1. Installationsbefehle überprüfen und ggf. korrigieren\\n  2. Erkennungsregeln anpassen (z. B. korrekten Pfad oder Registry-Schlüssel prüfen)\\n  3. App manuell deinstallieren und neu zuweisen","praevention":"Apps vor der Zuweisung auf einem Referenzgerät testen\\n\\n---"},{"titel":"Benutzer kann sich nicht anmelden — Conditional Access blockiert Zugriff","symptom":"Benutzer meldet sich mit korrekten Zugangsdaten an, erhält aber Zugriffsverweigerung","ursache":"Conditional Access-Richtlinie blockiert den Zugriff (z. B. Gerät nicht compliant, falscher Standort)","diagnose_schritte":["Prüfe die Anmelde-Protokolle in Entra ID unter \\"Überwachen\\" → \\"Anmelde-Protokolle\\"","Prüfe, welche Conditional Access-Richtlinie den Zugriff blockiert hat","Prüfe die Geräte-Compliance in Intune"],"loesung":"1. Geräte-Compliance prüfen und ggf. Compliance-Richtlinie anpassen\\n  2. Conditional Access-Richtlinie anpassen (z. B. Ausnahme für bestimmte Benutzergruppe)\\n  3. Benutzer über den Blockierenden Zustand informieren und Lösung kommunizieren","praevention":"Conditional Access-Richtlenien erst im \\"Berichtsmodus\\" aktivieren, bevor sie erzwungen werden\\n\\n---"},{"titel":"Passwort-Reset funktioniert nicht — SSPR konfiguriert falsch","symptom":"Benutzer kann Passwort nicht über Self-Service Password Reset (SSPR) zurücksetzen","ursache":"SSPR ist nicht aktiviert oder die Authentifizierungsmethoden sind falsch konfiguriert","diagnose_schritte":["Prüfe unter Entra ID → \\"Kennwortzurücksetzung\\" ob SSPR aktiviert ist","Prüfe, welche Authentifizierungsmethoden konfiguriert sind","Prüfe, ob der Benutzer für SSPR berechtigt ist (Gruppenzuweisung)"],"loesung":"1. SSPR in Entra ID aktivieren\\n  2. Mindestens eine Authentifizierungsmethode konfigurieren (z. B. E-Mail oder Mobiltelefon)\\n  3. SSPR-Benutzergruppe überprüfen","praevention":"SSPR bei der Einführung von Entra ID konfigurieren und Schulungsmaterial für Benutzer bereitstellen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was ist der Hauptunterschied zwischen MDM und MAM bei Intune?","optionen":["MDM verwaltet nur Windows-Geräte, MAM nur mobile Geräte","MDM verwaltet das gesamte Gerät, MAM verwaltet nur einzelne Apps","MDM ist kostenlos, MAM kostet extra","Es gibt keinen Unterschied"],"antwort":1,"erklaerung":"MDM (Mobile Device Management) verwaltet das gesamte Gerät, MAM (Mobile Application Management) verwaltet nur einzelne Apps, auch auf BYOD-Geräten. Quelle: Microsoft Learn — \\"What is Microsoft Intune?\\" — abgerufen am 2026-10-19."},{"nummer":2,"frage":"Was ist der erste Schritt beim Bereitstellen einer Win32-App in Intune?","optionen":["App in ein `.intunewin`-Paket konvertieren","App im Microsoft Store suchen","App manuell auf jedem Gerät installieren","Conditional Access-Richtlinie erstellen"],"antwort":0,"erklaerung":"Die Win32-App muss zuerst mit dem Microsoft Win32 Content Prep Tool in ein `.intunewin`-Paket konvertiert werden. Quelle: Microsoft Learn — \\"What is Microsoft Intune?\\" — abgerufen am 2026-10-19."},{"nummer":3,"frage":"Was bedeutet der Begriff \\"Tenant\\" in Entra ID?","optionen":["Ein physischer Server im Rechenzentrum","Eine Instanz von Entra ID für eine Organisation","Ein Benutzerkonto","Ein Netzwerksegment"],"antwort":1,"erklaerung":"Ein Tenant ist eine Instanz von Entra ID, die einer Organisation zugeordnet ist. Quelle: Microsoft Learn — \\"What is Microsoft Entra ID?\\" — abgerufen am 2026-10-19."},{"nummer":4,"frage":"Welche Deployment-Methode ist für große Umgebungen mit hunderten Geräten am besten geeignet?","optionen":["Manuelle Installation","MDM-basiertes Deployment über Intune","Windows Update","Manuelles Kopieren von Dateien"],"antwort":1,"erklaerung":"MDM-basiertes Deployment über Intune ist für große Umgebungen am besten geeignet, da es skalierbar und zentral verwaltbar ist. Quelle: Microsoft Learn — \\"What is Microsoft Intune?\\" — abgerufen am 2026-10-19."},{"nummer":5,"frage":"Was tun, wenn ein Benutzer sich nicht anmelden kann und Conditional Access den Zugriff blockiert?","optionen":["Das Benutzerkonto löschen","Die Conditional Access-Richtlinie prüfen und ggf. anpassen","Den Benutzer ignorieren","Den PC neu aufsetzen"],"antwort":1,"erklaerung":"Die Conditional Access-Richtlinie muss geprüft und ggf. angepasst werden (z. B. Geräte-Compliance überprüfen). Quelle: Microsoft Learn — \\"What is Microsoft Intune?\\" — abgerufen am 2026-10-19."}],"ticket":[{"situation":"Ein neuer Mitarbeiter (Herr Schmidt) erhält sein neues Firmen-Laptop. Das Gerät ist mit Entra ID verbunden, wird aber nicht in Intune registriert. Der Mitarbeiter kann sich nicht bei den Unternehmens-Apps anmelden und bittet um Hilfe.","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP2 (Hoch) — Der Mitarbeiter kann nicht arbeiten, aber es handelt sich um einen einzelnen Benutzer, nicht um einen systemweiten Ausfall.\\n\\n**2. Diagnose:**\\n- Prüfe, ob das Gerät mit Entra ID verbunden ist (Einstellungen → Konten → Auf Arbeits- oder Schulkonto zugreifen)\\n- Prüfe, ob eine Intune-Lizenz für den Benutzer Herr Schmidt zugewiesen ist\\n- Prüfe unter Entra ID → Mobility (MDM und MAM) → Microsoft Intune die MDM-Benutzereinstellung\\n- Prüfe, ob die automatische Registrierung aktiviert ist\\n\\n**3. Lösung:**\\n- Intune-Lizenz für Herr Schmidt zuweisen (falls nicht vorhanden)\\n- Automatische Registrierung in Entra ID aktivieren (falls nicht konfiguriert)\\n- Gerät neu starten und Registrierung erzwingen\\n- Alternative: Herr Schmidt registriert das Gerät manuell über die Company Portal-App\\n\\n**4. Dokumentation:**\\n- Problem: Neues Gerät wird nicht automatisch in Intune registriert\\n- Ursache: Intune-Lizenz fehlt oder automatische Registrierung ist nicht konfiguriert\\n- Lösung: Intune-Lizenz zuweisen, automatische Registrierung aktivieren, Gerät neu starten\\n- Verifizierung: Gerät erscheint in Intune und Mitarbeiter kann sich bei Unternehmens-Apps anmelden\\n\\n---"}],"slug":"modul-14-deployment"},{"title":"Modul 15: Backup, Recovery, Patch-Management","level":2,"module":15,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/wbadmin","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/deployment/update/waas-manage-updates-wsus","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/privacy/windows-diagnostic-data","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/whats-new/whats-new-windows-11-version-23h2","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Backup ohne Recovery-Test","symptom":"Nach einem Hardware-Defekt stellt sich heraus, dass das Backup beschädigt oder unlesbar ist","ursache":"Backup wurde erstellt, aber nie eine Wiederherstellung getestet","diagnose_schritte":["Prüfe die Backup-Datei auf Integrität (Größe, Zeitstempel)","Versuche eine einzelne Datei aus dem Backup wiederherzustellen","Prüfe, ob das Backup-Laufwerk lesbar ist"],"loesung":"- Recovery-Test durchführen (mindestens quartalsweise)\\n  - Backup auf neues Medium migrieren, falls Fehler erkannt\\n  - Zwei Backup-Medien verwenden (3-2-1-Regel)","praevention":"Automatisierte Recovery-Tests in den Backup-Zeitplan integrieren\\n\\n---"},{"titel":"System-Image auf anderer Hardware wiederhergestellt","symptom":"BSOD (Blue Screen) nach Systemimage-Wiederherstellung auf einen anderen PC","ursache":"Systemimage ist hardwaregebunden (andere CPU, Chipsatz, Treiber)","diagnose_schritte":["Starte im abgesicherten Modus (F8 oder Shift + Neustart)","Prüfe die angeschlossenen Treiber (Geräte-Manager)","Deinstalliere Hardware-spezifische Treiber"],"loesung":"- Treiber der Zielhardware installieren\\n  - Falls nicht bootfähig: Wiederherstellungsmedium verwenden und Reparatur starten","praevention":"Systemimages nur für identische Hardware verwenden; für Hardwarewechsel Dateibackup + saubere Installation bevorzugen\\n\\n---"},{"titel":"Patches ohne Test direkt auf Produktivsysteme","symptom":"Nach dem Update startet ein kritischer Dienst nicht mehr (z. B. Datenbank, Buchhaltungs-Software)","ursache":"Update wurde ohne Testumgebung auf allen Systemen gleichzeitig installiert","diagnose_schritte":["Updateverlauf prüfen (Einstellungen → Windows Update → Updateverlauf)","Identifiziere das zuletzt installierte Update","Prüfe Hersteller-Kompatibilität der betroffenen Software"],"loesung":"- Problematic Update deinstallieren (Updateverlauf → Updates deinstallieren)\\n  - Warten auf Korrektur-Update\\n  - Auf betroffenen Systemen Update pausieren","praevention":"Ringweiser Rollout — erst Testgruppe, dann Pilotgruppe, dann gesamte Produktionsumgebung\\n\\n---"},{"titel":"Kein Offline-Backup — Ransomware verschlüsselt auch Backup-Laufwerk","symptom":"Sowohl Produktionsdaten als auch das angeschlossene Backup-Laufwerk sind verschlüsselt","ursache":"Backup-Laufwerk war dauerhaft angeschlossen und wurde von der Ransomware mitverschlüsselt","diagnose_schritte":["Prüfe, welche Laufwerke verschlüsselt sind (Dateierweiterung, Readme-Datei)","Identiziere die Ransomware-Variante","Prüfe, ob ein offline Backup (nicht angeschlossen) existiert"],"loesung":"- Offline-Backup herstellen\\n  - Falls nicht vorhanden: Versuch einer Entschlüsselung (NoMoreRansom.org) oder neu aufsetzen","praevention":"Mindestens ein Backup-Laufwerk physischalisch trennen oder Cloud-Backup mit Versionierung verwenden\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was besagt die 3-2-1-Backup-Regel?","optionen":["3 Backups, 2 Medien, 1 Cloud","3 Kopien der Daten, 2 verschiedene Medien, 1 Kopie offline","3 verschiedene Backup-Typen, 2 Wiederherstellungen, 1 Test","3 Tage zwischen Backups, 2 Laufwerke, 1 Administrator"],"antwort":1,"erklaerung":"3 Kopien, 2 Medien, 1 Kopie offline."},{"nummer":2,"frage":"Welcher Backup-Typ benötigt bei der Wiederherstellung das Vollbackup UND alle Inkrementaldaten?","optionen":["Vollbackup","Differenzialbackup","Inkrementellbackup","Systemimage"],"antwort":2,"erklaerung":"Inkrementelle Backups brauchen die komplette Sequenz."},{"nummer":3,"frage":"Was ist der Hauptunterschied zwischen einem System-Image-Backup und einem Datei-Backup?","optionen":["Ein System-Image ist immer kleiner","Ein System-Image enthält Windows, Programme, Einstellungen und Dateien; ein Datei-Backup nur ausgewählte Dateien","Ein Datei-Backup ist schneller","Es gibt keinen Unterschied"],"antwort":1,"erklaerung":"System-Image = komplettes Laufwerk, Datei-Backup = ausgewählte Dateien."},{"nummer":4,"frage":"Was bedeutet WSUS?","optionen":["Windows System Update Service","Windows Server Update Services","Windows Security Update System","Windows Software Update Service"],"antwort":1,"erklaerung":"Windows Server Update Services."},{"nummer":5,"frage":"Warum muss ein Backup regelmäßig auf Wiederherstellbarkeit getestet werden?","optionen":["Weil Microsoft es vorschreibt","Weil sich sonst die Backup-Datei automatisch löscht","Weil nur ein erfolgreicher Recovery-Test die Integrität beweist","Weil das Backup-Laufwerk sonst defekt wird"],"antwort":2,"erklaerung":"Nur ein erfolgreicher Recovery-Test beweist, dass das Backup brauchbar ist."}],"ticket":[{"situation":"Die Buchhaltung meldet: \\"Seit dem Windows Update gestern Abend startet Excel nicht mehr. Es kommt sofort ein Fehler \'Excel kann nicht gestartet werden\'. Wir müssen heute die Monatsabschluss machen — bitte schnell!\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Was ist die langfristige Prävention?","loesung":"**1. Priorität:**\\nP1 (Kritisch) — die Buchhaltung kann nicht arbeiten, betriebskritisch.\\n\\n**2. Diagnose:**\\n- Prüfe den Updateverlauf (Einstellungen → Windows Update → Updateverlauf)\\n- Identifiziere das Update vor dem Problemstart\\n- Prüfe, ob weitere Benutzer betroffen sind (Hardware- oder softwareseitig)\\n- Prüfe das Anwendungsereignisprotokoll (Ereignisanzeige → Windows-Protokolle → Anwendung)\\n\\n**3. Lösung:**\\n- Problematic Update deinstallieren: Einstellungen → Windows Update → Updateverlauf → Updates deinstallieren → das betroffende KB entfernen\\n- Alternativ: Systemwiederherstellung auf einen Punkt vor dem Update\\n- Falls Excel weiterhin nicht startet: Office-Reparatur starten (Einstellungen → Apps → Installierte Apps → Microsoft 365 → Ändern → Schnellreparatur)\\n\\n**4. Prävention:**\\n- Patch-Management mit Testgruppe einführen\\n- Updates nicht auf allen Systemen gleichzeitig ausrollen\\n- Ringweiser Rollout: Test → Pilot → Produktion\\n\\n---"}],"slug":"modul-15-backup-patch"},{"title":"Modul 16: Incident- und Problem-Management (ITIL), Dokumentation, Wissensdatenbank","level":2,"module":16,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.ibm.com/think/topics/it-infrastructure-library","abrufdatum":"2026-10-19"},{"url":"https://www.itil.org.uk/training/itil-foundation-level-courses/itil-foundation-training","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Incident und Problem werden nicht unterschieden","symptom":"Wiederkehrende Incidents, keine Ursachenanalyse","ursache":"Team schließt Incidents mit Workaround, aber Problem bleibt unbemerkt","diagnose_schritte":["Suche in den letzten 30 Tickets nach wiederkehrenden Symptomen","Identifiziere Ticket mit gleicher Kategorie und ähnlicher Beschreibung","Prüfe, ob ein Problem-Ticket existiert"],"loesung":"- Problem-Ticket für das wiederkehrende Symptom erstellen\\n  - Alle betroffenen Incidents mit dem Problem-Ticket verknüpfen\\n  - Root-Cause-Analyse (z. B. 5 Whys) durchführen","praevention":"Nach jedem Incident die Frage: „Ist das ein Symptom eines größeren Problems?\\"\\n- Quelle: ITIL 4 Foundation, abgerufen am 2026-10-19\\n\\n---"},{"titel":"Known Error nicht in der KEDB dokumentiert","symptom":"Kollege findet keine Lösung für wiederkehrendes Problem","ursache":"Problem wurde gelöst, aber nicht als Known Error dokumentiert","diagnose_schritte":["Prüfe die Ticket-Historie auf gelöste Probleme","Identifiziere Probleme mit dokumentierter Lösung","Prüfe, ob diese in der KEDB erfasst sind"],"loesung":"- Known Error-Eintrag in der KEDB erstellen\\n  - Lösung und Workaround detailliert beschreiben\\n  - Betroffene Incidents verknüpfen","praevention":"Nach jeder Problem-Lösung automatisch KEDB-Eintrag erstellen\\n- Quelle: ITIL 4 Foundation, abgerufen am 2026-10-19\\n\\n---"},{"titel":"Wissensdatenbank veraltet und ungenutzt","symptom":"Nutzer finden keine aktuellen Lösungen, stellen wiederholt Tickets","ursache":"Wissensdatenbank wird nicht geprüft und aktualisiert","diagnose_schritte":["Zähle die Artikel in der Wissensdatenbank","Prüfe die letzte Änderung der 10 ältesten Artikel","Vergleiche mit den häufigsten Ticket-Kategorien"],"loesung":"- Regelmäßigen Review-Prozess einführen (quartalsweise)\\n  - Nicht mehr zutreffende Artikel archivieren\\n  - Verknüpfung zu den Top-10-Ticket-Kategorien herstellen","praevention":"Verantwortliche Person für Wissensdatenbank benennen\\n- Quelle: IBM ITIL Overview, abgerufen am 2026-10-19\\n\\n---"},{"titel":"Dokumentation unvollständig oder unverständlich","symptom":"Kollege kann übernommenes Ticket nicht bearbeiten","ursache":"Ticket wurde mit unklaren oder fehlenden Informationen geschlossen","diagnose_schritte":["Öffne 10 zufällig gewählte Tickets der letzten Woche","Prüfe, ob alle Felder (Beschreibung, Diagnose, Lösung, Verifizierung) ausgefüllt sind","Frage dich: „Könnte ein Kollege das Ticket ohne weitere Informationen bearbeiten?\\""],"loesung":"- Tickets nachbearbeiten und Lücken schließen\\n  - Dokumentations-Checkliste einführen:\\n    - [ ] Beschreibung des Problems\\n    - [ ] Diagnose-Schritte\\n    - [ ] Lösung / Workaround\\n    - [ ] Verifizierung (Problem bestätigt gelöst?)\\n    - [ ] Verknüpfung zu betroffenen Incidents/Problemen","praevention":"Dokumentationsstandard bei der Team-Schulung vermitteln\\n- Quelle: IBM ITIL Overview, abgerufen am 2026-10-19\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was ist die ITIL-Definition eines Incidents?","optionen":["Eine geplante Wartung eines IT-Services","Eine ungeplante Unterbrechung oder Qualitätsminderung eines IT-Service","Eine Anfrage nach neuer Hardware","Ein dokumentiertes Problem mit bekannter Lösung"],"antwort":1,"erklaerung":"„Ein Incident ist eine ungeplante Unterbrechung eines IT-Service oder eine Qualitätsminderung eines IT-Service.\\" Quelle: ITIL 4 Foundation, abgerufen am 2026-10-19"},{"nummer":2,"frage":"Was ist der Hauptunterschied zwischen Incident Management und Problem Management?","optionen":["Incident Management ist schneller als Problem Management","Incident Management stellt den Service wieder her, Problem Management beseitigt die Ursache","Problem Management ist nur für kritische Incidents","Es gibt keinen Unterschied"],"antwort":1,"erklaerung":"Incident Management fokussiert auf Wiederherstellung, Problem Management auf Ursachenbeseitigung. Quelle: ITIL 4 Foundation, abgerufen am 2026-10-19"},{"nummer":3,"frage":"Was ist ein Known Error?","optionen":["Ein Incident, der noch nicht gelöst ist","Ein Problem, das diagnostiziert wurde und für das eine dokumentierte Lösung oder ein Workaround vorhanden ist","Ein Fehler in der Software","Ein Problem, das nie auftritt"],"antwort":1,"erklaerung":"„Ein Known Error ist ein Problem, das diagnostiziert wurde und für das eine dokumentierte Lösung oder ein dokumentierter Workaround vorhanden ist.\\" Quelle: ITIL 4 Foundation, abgerufen am 2026-10-19"},{"nummer":4,"frage":"Was ist das Ziel des Service Knowledge Management System (SKMS)?","optionen":["Alle Mitarbeiter zu überwachen","Wissen und Informationen zu verwalten und zugänglich zu machen","Tickets automatisch zu lösen","Hardware-Inventar zu verwalten"],"antwort":1,"erklaerung":"Das SKMS ist ein System zur Verwaltung von Wissen und Informationen. Quelle: ITIL 4 Foundation, abgerufen am 2026-10-19"},{"nummer":5,"frage":"Welche Methode eignet sich am besten für die Ursachenanalyse eines komplexen Netzwerkproblems mit mehreren Einflussfaktoren?","optionen":["5 Whys","Ishikawa-Diagramm","Passwort-Reset","Neustart des Rechners"],"antwort":1,"erklaerung":"Das Ishikawa-Diagramm eignet sich für komplexe Probleme mit mehreren Einflussfaktoren. Quelle: IBM ITIL Overview, abgerufen am 2026-10-19"}],"ticket":[{"situation":"Zwei Mitarbeiter aus unterschiedlichen Abteilungen melden sich zeitgleich mit dem gleichen Problem: „Ich kann seit heute Morgen nicht auf die Dateifreigabe zugreifen. Ich erhalte die Fehlermeldung „Zugriff verweigert\\". Ich habe gestern mein Passwort geändert.\\"","aufgabe":"1. Erstelle ein Incident-Ticket für jeden Melder\\n2. Erstelle ein Problem-Ticket (da mehrere Benutzer betroffen sind)\\n3. Führe eine vereinfachte Root-Cause-Analyse durch (5 Whys)\\n4. Dokumentiere den Fall in der Wissensdatenbank","loesung":"**1. Incident-Tickets:**\\n\\n| Feld | Ticket 1 | Ticket 2 |\\n|------|---------|----------|\\n| Beschreibung | Kein Zugriff auf Dateifreigabe, „Zugriff vergendert\\" nach Passwort-Änderung | Identisch |\\n| Kategorie | Netwerk / Dateifreigabe | Netwerk / Dateifreigabe |\\n| Priorität | P2 (zwei Benutzer, Workaround vorhanden) | P2 |\\n| Status | In Bearbeitung | In Bearbeitung |\\n\\n**2. Problem-Ticket:**\\n\\n| Feld | Eintrag |\\n|------|---------|\\n| Beschreibung | Mehrere Benutzer können nach Passwort-Änderung nicht auf Dateifreigabe zugreifen |\\n| Kategorie | Authentifizierung / Dateifreigabe |\\n| Auslöser | Mehrere Incidents mit gleichem Symptom |\\n| Verknüpfte Incidents | Ticket-1, Ticket-2 |\\n| Status | In Bearbeitung |\\n\\n**3. Root-Cause-Analyse (5 Whys):**\\n- Warum können die Benutzer nicht zugreifen? → Ihre Anmeldeinformationen werden nicht akzeptiert\\n- Warum werden die Anmeldeinformationen nicht akzeptiert? → Das geänderte Passwort wurde nicht an den Dateifreigabe-Dienst weitergegeben\\n- Warum wurde das Passwort nicht weitergegeben? → Die zwischengespeicherten Windows-Anmeldeinformationen (Credential Manager) enthalten noch das alte Passwort\\n- Warum enthält der Credential Manager das alte Passwort? → Das Passwort wurde geändert, aber der Credential Manager nicht aktualisiert\\n- Warum wurde der Credential Manager nicht aktualisiert? → Keine automatische Synchronisation zwischen AD-Passwort und Credential Manager\\n\\n**Ursache:** Credential Manager enthält veraltete Anmeldeinformationen.\\n\\n**4. Lösung:**\\n- Credential Manager öffnen (Systemsteuerung → Benutzerkonten → Credential Manager)\\n- Gespeicherte Windows-Anmeldeinformationen für die Dateifreigabe finden und entfernen\\n- Neue Anmeldung mit aktuellem Passwort durchführen\\n\\n**5. Wissensdatenbank-Artikel:**\\n- **Titel:** Dateifreigabe „Zugriff verweigert\\" nach Passwort-Änderung\\n- **Symptom:** Nach einer Passwort-Änderung erhalten Benutzer beim Zugriff auf die Dateifreigabe die Fehlermeldung „Zugriff verweigert\\"\\n- **Ursache:** Veraltete Anmeldeinformationen im Windows Credential Manager\\n- **Lösung:** Credential Manager öffnen, veraltete Einträge entfernen, neu anmelden\\n- **Tags:** Dateifreigabe, Passwort, Credential Manager, Zugriff verweigert\\n\\n---"}],"slug":"modul-16-itil"},{"title":"Modul 17: Abschlussprojekt + Prüfungssimulation","level":2,"module":17,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.comptia.org/certifications/a","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/training/","abrufdatum":"2026-10-19"},{"url":"https://www.ihk.de/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows/","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Zeitmanagement in der Prüfung schlecht","symptom":"Nicht alle Fragen bearbeitet, obwohl die Antworten gewusst wurden","ursache":"Zu viel Zeit für einzelne Fragen aufgewendet","diagnose_schritte":["Nach der Prüfung: Wie viel Zeit habe ich pro Frage gebraucht?","Identifiziere, welche Fragearten am meisten Zeit beansprucht haben","Prüfe, ob du PBQs zuerst oder zuletzt bearbeitet hast"],"loesung":"- In der Prüfung: Maximal 1 Minute pro Multiple-Choice-Frage\\n  - PBQs zuerst bearbeiten (diese sind am zeitraubendsten)\\n  - Unsicher gemarkte Fragen überspringen und später nacharbeiten","praevention":"Zeitübungen im Vorfeld durchführen — 3 Mal 90-Minuten-Simulationen absolvieren\\n\\n---"},{"titel":"PBQs (Performance-Based Questions) falsch angegangen","symptom":"Fragen übersprungen oder falsch gelöst, obwohl der Stoff bekannt war","ursache":"Keine Erfahrung mit der simulierten Umgebung","diagnose_schritte":["Prüfe, ob du in der Vorbereitung Übungsaufgaben mit simulierten Umgebungen gemacht hast","Überlege, ob du die Aufgabe richtig verstanden hast, bevor du loslegst","Analysiere, ob du das notwendige Hintergrundwissen hattest"],"loesung":"- CompTIA bietet offizielle Übungstests mit PBQs an (Practice Tests)\\n  - Microsoft Learn bietet interaktive Labs für Windows-Konfiguration\\n  - Übe mit virtuellen Maschinen, um die Oberfläche kennenzulernen","praevention":"Mindestens 2 komplette Practice-Tests mit PBQs absolvieren\\n\\n---"},{"titel":"Dokumentation unvollständig","symptom":"Kollege kann übernommene Tickets nicht bearbeiten, fehlende Infos","ursache":"Routine-Mangel, Dokumentation als nachträgliche Aufgabe empfunden","diagnose_schritte":["Prüfe 5 zufällige Tickets auf Vollständigkeit","Stelle die Frage: „Könnte ein Kollege ohne Rückfragen weiterarbeiten?\\"","Identifiziere fehlende Felder (Befund, Lösung, Verifizierung)"],"loesung":"- Vor der Schließung eines Tickets: Checkliste durchgehen\\n  - Template für häufige Anfragen erstellen (Passwort-Reset, Drucker-Einrichtung, etc.)\\n  - Peer-Review: Kollege prüft die Dokumentation","praevention":"Dokumentation als festen Bestandteil des Ticket-Workflows etablieren\\n\\n---"},{"titel":"Prüfungsangst und unvorbereiteter Start","symptom":"Panik in der Prüfung, Fragen werden falsch gelesen","ursache":"Unzureichende Vorbereitung, keine Simulationsprüfungen absolviert","diagnose_schritte":["Bewerte dein Vorbereitungsniveau ehrlich (1–10)","Prüfe, ob du alle Prüfungsthemen abgedeckt hast","Überlege, ob du ausreichend Schlaf und Pausen in der Vorbereitung eingebaut hast"],"loesung":"- 2 Wochen vor der Prüfung: Tägliche 30-Minuten-Übungen\\n  - 1 Woche vor der Prüfung: Vollständige Simulation unter realen Bedingungen\\n  - 1 Tag vor der Prüfung: Keine neuen Themen mehr, nur Wiederholung","praevention":"Frühzeitige Planung — mindestens 4 Wochen Vorbereitungszeit einplanen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Wie lange dauert eine CompTIA A+-Prüfung?","optionen":["60 Minuten","90 Minuten","120 Minuten","180 Minuten"],"antwort":1,"erklaerung":"90 Minuten pro Prüfung."},{"nummer":2,"frage":"Was bedeutet die Abkürzung PBQ?","optionen":["Performance-Based Question","Practice-Based Quiz","Pre-Board Question","Personal Benchmark Query"],"antwort":0,"erklaerung":"Performance-Based Question."},{"nummer":3,"frage":"Welche A+-Prüfung behandelt Betriebssysteme und Sicherheit?","optionen":["220-1101 (Core 1)","220-1102 (Core 2)","220-1103 (Core 3)","220-1104 (Core 4)"],"antwort":1,"erklaerung":"220-1102 (Core 2) behandelt Operating Systems, Security und Software Troubleshooting."},{"nummer":4,"frage":"Welches ist die beste Methode, um Prüfungsangst zu reduzieren?","optionen":["Viele neue Themen kurz vor der Prüfung lernen","Simulationsprüfungen unter realen Bedingungen absolvieren","Ausreichend Schlaf in der Nacht vor der Prüfung","Koffein in großen Mengen konsumieren"],"antwort":1,"erklaerung":"Simulationsprüfungen schaffen Vertrautheit mit dem Format und reduzieren Unsicherheit."},{"nummer":5,"frage":"Was ist der wichtigste Bestandteil der Ticket-Dokumentation?","optionen":["Lange, komplexe Sätze","Alle Schritte, Befunde und Lösungen nachvollziehbar dokumentieren","Nur das Endergebnis notieren","Persönliche Meinungen zum Benutzer einfügen"],"antwort":1,"erklaerung":"Nachvollziehbarkeit ist das A und O der Dokumentation."}],"ticket":[{"situation":"Du bist der IT-Support der Muster GmbH (50 Mitarbeiter). Am Montagmorgen kommen drei Tickets gleichzeitig:","aufgabe":"1. Priorisiere die Tickets und begründe deine Reihenfolge.\\n2. Beschreibe deine Diagnose für T1 in 4 Schritten.\\n3. Was ist dein erster Schritt bei T2?\\n4. Erstelle eine Checkliste für T3 (neuer Arbeitsplatz).","loesung":"**1. Priorisierung:**\\n\\n| Ticket | Priorität | Begründung |\\n|--------|-----------|------------|\\n| T1 | P1 | Kompletter Serverausfall, kein Workaround, alle betroffen |\\n| T2 | P2 | Einzelne Software, Workaround möglich (anderes Office-Programm) |\\n| T3 | P3 | Standard-Request, kein Produktionsstopp |\\n\\n**2. Diagnose T1 (Server-Ausfall):**\\n\\n1. **Physikalische Prüfung:** Ist der Server angeschlossen? LED-Status? Lüfter?\\n2. **POST/BIOS:** Einstecken und beobachten — Fehlermeldungen notieren\\n3. **Monitor anschließen:** Bekomme ich ein Bild? BIOS-Post-Codes deuten auf Hardware-Fehler hin\\n4. **Hardware isolate:** Netzteil, RAM, Kabel prüfen — ggf. Ersatzteile testen\\n\\n**3. Erster Schritt T2 (Excel-Problem):**\\n\\n- Windows Update-Verlauf prüfen: `Einstellungen → Windows Update → Updateverlauf`\\n- Reparatur von Office starten: `Systemsteuerung → Programme → Microsoft Office → Ändern → Schnellreparatur`\\n- Alternativ: Office-Reparatur über `C:\\\\Program Files\\\\Microsoft Office\\\\root\\\\Office16\\\\officec2rclient.exe` (Version variiert)\\n\\n**4. Checkliste T3 (neuer Arbeitsplatz):**\\n\\n- [ ] PC/Laptop bereitstellen und anschließen\\n- [ ] Windows-Benutzerkonto im AD anlegen\\n- [ ] E-Mail-Postfach erstellen und Outlook konfigurieren\\n- [ ] Teams-Client installieren und anmelden\\n- [ ] Drucker-Zugriff einrichten\\n- [ ] NTFS-Rechte auf benötigte Freigaben setzen\\n- [ ] Willkommens-E-Mail mit Zugangsdaten versenden\\n- [ ] Erstlogin und Funktionstest durchführen\\n\\n---"}],"slug":"modul-17-abschluss"},{"title":"Modul 18: Linux & macOS für den IT-Support","level":1,"module":18,"last_verified":"2026-10-26","windows_version":"—","schwerpunkt":["Bash","Dateisysteme","macOS","Support-Szenarien"],"sources":[{"url":"https://www.linux.com/","abrufdatum":"2026-10-26"},{"url":"https://support.apple.com/de-de/ht201261","abrufdatum":"2026-10-26"}],"fehler":[],"quiz":[],"ticket":[],"slug":"modul-18-linux-macos"},{"title":"Modul 19: Cloud & Identity Vertiefung","level":2,"module":19,"last_verified":"2026-10-26","windows_version":"—","schwerpunkt":["Entra ID","Hybrid Join","Conditional Access","MFA","Intune"],"sources":[{"url":"https://learn.microsoft.com/de-de/entra/","abrufdatum":"2026-10-26"},{"url":"https://learn.microsoft.com/de-de/training/modules/manage-identities-microsoft-entra-id/","abrufdatum":"2026-10-26"}],"fehler":[],"quiz":[],"ticket":[],"slug":"modul-19-cloud-identity"},{"title":"Modul 2: Hardware — PC-Aufbau, Diagnose, Peripherie, Drucker","level":1,"module":2,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"},{"url":"https://www.professormesser.com/free-a-plus-training/220-1101/220-1101-video/220-1101-training-course/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/troubleshoot-device-driver-failures/2-examine-tools-manage-troubleshoot-device-drivers","abrufdatum":"2026-10-19"},{"url":"https://support.microsoft.com/en-us/windows/hardware/printer/fix-printer-not-found-and-printer-not-recognized-errors-in-windows","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"PC startet nicht — PSU-Problem","symptom":"PC reagiert nicht auf den Power-Button, keine Lüfter, keine LEDs","ursache":"Netzteil defekt oder nicht korrekt angeschlossen","diagnose_schritte":["Prüfe, ob das Netzkabel in der Steckdose und im PSU steckt","Prüfe, ob der Netzschalter am PSU auf \\"I\\" (ein) steht","Prüfe, ob das 24-Pin-Motherboard-Kabel und das 8-Pin-CPU-Kabel fest sitzen","Falls verfügbar: PSU mit einem Multimeter testen oder gegen einen bekannten guten PSU tauschen"],"loesung":"- PSU austauschen (nur durch geschultes Personal!)\\n  - Korrekte Wattzahl beachten (mindestens 20 % Reserve)","praevention":"PSU-Auswahl immer mit Reserve planen, qualitativ hochwertige Komponenten verwenden\\n\\n---"},{"titel":"Blue Screen — RAM-Problem","symptom":"PC startet, aber irgendwann BSOD mit MEMORY_MANAGEMENT oder CRITICAL_PROCESS_DIED","ursache":"Defektes RAM-Modul oder falscher RAM-Typ","diagnose_schritte":["BSOD-Fehlercode notieren","Windows Memory Diagnostic ausführen: `mdsched.exe` → Neustart","Bei Fehler: Module einzeln testen (eines nach dem anderen entfernen)","RAM-Typ mit Motherboard-Kompatibilität prüfen"],"loesung":"- Defektes RAM-Modul austauschen\\n  - Module korrekt einsetzen (bis der Klick zu hören ist)\\n  - Kompatiblen RAM-Typ verwenden (DDR4/DDR5 je nach Motherboard)","praevention":"RAM-Käufe immer an Motherboard-Sockel anpassen\\n\\n---"},{"titel":"USB-Gerät wird nicht erkannt","symptom":"USB-Gerät angeschlossen, aber Windows zeigt nichts an oder \\"USB-Gerät nicht erkannt\\"","ursache":"Treiberproblem, defektes Kabel, defekter USB-Port oder Gerät defekt","diagnose_schritte":["Gerät an einem anderen USB-Port testen","Gerät an einem anderen PC testen","Kabel tauschen","Geräte-Manager → USB-Controller → Treiber aktualisieren","Gerät deinstallieren und neu starten"],"loesung":"- Treiber aktualisieren oder neu installieren\\n  - USB-Port oder Kabel austauschen\\n  - Falls Gerät defekt: Austausch","praevention":"Hohe Kabelqualität verwenden, Geräte sicher entfernen (Safely Remove Hardware)\\n\\n---"},{"titel":"Drucker druckt nicht","symptom":"Drucker ist angeschlossen, aber Druckaufträge bleiben in der Warteschlange oder es wird nichts gedruckt","ursache":"Treiberproblem, Verbindungsproblem, Papierstau oder Druckerwarteschlange blockiert","diagnose_schritte":["Prüfe, ob Drucker eingeschaltet ist","Prüfe die Verbindung (USB-Kabel oder Netzwerk)","Prüfe die Druckwarteschlange: Start → \\"Drucker und Scanner\\" → Drucker wählen → \\"Druckwarteschlange öffnen\\"","Falls Aufträge hängen: Warteschlause leeren (Alle Aufträge abbrechen)","Testseite drucken: Einstellungen → Drucker → \\"Testseite drucken\\"","Treiber prüfen: Geräte-Manager → Drucker → Treiber aktualisieren"],"loesung":"- Druckwarteschlange leeren und neu starten\\n  - Treiber aktualisieren oder neu installieren\\n  - Verbindung prüfen (Kabel/Netzwerk)\\n  - Drucker-Einstellungen prüfen (Papier, Farbe, Duplex)","praevention":"Regelmäßige Wartung, aktuelle Treiber, Druckwarteschlause bei Störungen zuerst prüfen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was bedeutet POST?","optionen":["Power Off System Test","Power On Self Test","Peripheral Operation System Test","Personal Office Startup Test"],"antwort":1,"erklaerung":"Power On Self Test."},{"nummer":2,"frage":"Ein PC startet nicht (keine Lüfter, keine LEDs). Was ist die wahrscheinlichste Ursache?","optionen":["Defekte Festplatte","Defektes Netzteil","Defekte Grafikkarte","Defekter Monitor"],"antwort":1,"erklaerung":"Defektes Netzteil (PSU-Problem)."},{"nummer":3,"frage":"Ein USB-Gerät wird nicht erkannt. Was ist der erste Schritt?","optionen":["Windows neu installieren","An einem anderen USB-Port testen","Treiber aktualisieren","PC neu starten"],"antwort":1,"erklaerung":"An einem anderen USB-Port testen."},{"nummer":4,"frage":"Welcher Fehlercode deutet auf ein RAM-Problem hin?","optionen":["CRITICAL_PROCESS_DIED","NTFS_FILE_SYSTEM","MEMORY_MANAGEMENT","DRIVER_IRQL_NOT_LESS_OR_EQUAL"],"antwort":2,"erklaerung":"MEMORY_MANAGEMENT."},{"nummer":5,"frage":"Was ist der erste Schritt bei einem Druckerproblem?","optionen":["Windows neu installieren","Druckerwarteschlange prüfen und leeren","Drucker zurücksetzen","Treiber deinstallieren"],"antwort":1,"erklaerung":"Druckerwarteschlange prüfen und leeren."}],"ticket":[{"situation":"Ein Mitarbeiter meldet: \\"Ich habe gestern einen neuen USB-Hub angeschlossen und seitdem funktioniert meine Tastatur nicht mehr. Die Maus geht noch. Ich habe schon versucht, die Tastatur an einen anderen USB-Port zu stecken, aber nichts hilft. Ich muss dringend meine E-Mails beantworten.\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP2 (Hoch) — E-Mail ist betriebskritisch, aber es gibt einen Workaround (Maus funktioniert, On-Screen-Tastatur).\\n\\n**2. Diagnose:**\\n- Prüfe, ob der USB-Hub korrekt angeschlossen ist und Strom hat\\n- Prüfe im Geräte-Manager, ob die Tastatur erkannt wird\\n- Prüfe, ob die Tastatur direkt (ohne Hub) an einem USB-Port funktioniert\\n- Prüfe die USB-Treiber im Geräte-Manager\\n- Prüfe, ob die Tastatur in den Windows-Einstellungen aktiviert ist\\n\\n**3. Lösung:**\\n- Tastatur direkt an einen USB-Port des PCs stecken (ohne Hub)\\n- Falls funktioniert: USB-Hub ist defekt oder liefert nicht genug Strom → Hub austauschen\\n- Falls nicht funktioniert: Tastatur defekt → austauschen\\n- Fallback: On-Screen-Tastatur verwenden (Windows: Windows-Taste + Strg + O)\\n\\n**4. Dokumentation:**\\n- Problem: USB-Hub verursachte Konflikt mit Tastatur\\n- Ursache: USB-Hub defekt oder unterversorgt\\n- Lösung: Tastatur direkt an PC-Port anschließen\\n- Verifizierung: Tastatur funktioniert direkt angeschlossen\\n\\n---"}],"slug":"modul-2-hardware"},{"title":"Modul 20: Kommunale & behördliche IT + Einstieg in den öffentlichen Dienst","level":2,"module":20,"last_verified":"2026-10-26","windows_version":"—","schwerpunkt":["OTRS","Fachverfahren","KeePass","Karriere","Öffentlicher Dienst"],"sources":[{"url":"https://www.oth-anken.de/","abrufdatum":"2026-10-26"},{"url":"https://service.bund.de/ ","abrufdatum":"2026-10-26"}],"fehler":[],"quiz":[],"ticket":[],"slug":"modul-20-kommunale-it"},{"title":"Modul 3: Windows 11 Grundlagen — Einstellungen, Konten, Updates, Treiber","level":1,"module":3,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/windows/deployment/update/windows-update-overview","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/windows-hardware/drivers/install/driver-signing","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/windows/identity-protection/hello-for-business/hello-overview","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/certifications/a","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Updates werden nicht installiert","symptom":"Windows Update meldet „Es sind keine Updates verfügbar\\" oder hängt bei 0 % / 99 %","ursache":"Beschädigte Windows Update-Komponenten, blockierte Dienste oder Plattenplatzmangel","diagnose_schritte":["Prüfe den freien Speicherplatz (mindestens 10 GB empfohlen für Feature-Updates)","Prüfe, ob der Windows Update-Dienst (wuauserv) läuft: `Get-Service wuauserv`","Öffne die Update-Verlauf — gibt es fehlgeschlagene Updates mit Fehlercode?","Führe die Windows Update-Fehlerbehebung aus: Einstellungen → System → Problembehandlung → Weitere Problembehandlungen → Windows Update"],"loesung":"- Den Windows Update-Dienst neu starten: `net stop wuauserv` → `net start wuauserv`\\n  - Den SoftwareDistribution-Ordner leeren (nach Stopp des Dienstes): `C:\\\\Windows\\\\SoftwareDistribution\\\\Download`\\n  - Den DISM- und SFC-Scan ausführen: `DISM /Online /Cleanup-Image /RestoreHealth` danach `sfc /scannow`","praevention":"Regelmäßig freien Speicherplatz prüfen und Updates nicht über den Zeitraum der Aktiven Stunden hinaus pausieren\\n\\n---"},{"titel":"Nach Treiber-Update funktioniert Hardware nicht mehr","symptom":"Gerät meldet Fehlercode 43 oder 10 im Geräte-Manager, Hardware reagiert nicht","ursache":"Kompatibilitätsproblem zwischen neuem Treiber und Hardware oder Windows-Version","diagnose_schritte":["Öffne den Geräte-Manager und prüfe den Fehlercode im Geräte-Status","Notiere aktuelle Treiberversion und Anbieter","Prüfe, ob ein vorheriger Treiber in den Systemwiederherstellungsverfügbar ist"],"loesung":"- Treiber zurücksetzen: Geräte-Manager → Gerät → Reiter „Treiber\\" → „Treiber zurücksetzen\\"\\n  - Falls nicht verfügbar: „Gerät deinstallieren\\" (Treiber entfernen) und neu starten\\n  - Alternativ: Neuester Treiber von der Hersteller-Website manuell installieren","praevention":"Vor wichtigen Treiber-Updates einen Systemwiederherstellungspunkt erstellen (`Win + R` → `rstrui.exe`)\\n\\n---"},{"titel":"Benutzer meldet „Ich kann mich nicht anmelden\\" nach Kontotyp-Wechsel","symptom":"Anmeldeseite zeigt falsche Kontoverknüpfung, PIN wird nicht akzeptiert, „Falsches Passwort\\"","ursache":"Lokales Konto wurde in Microsoft-Konto umgewandelt oder umgekehrt; Anmeldeinformationen-Cache ist inkonsistent","diagnose_schritte":["Frage den Benutzer: Wann trat das Problem erstmals auf? Gab es einen Kontotyp-Wechsel?","Prüfe, ob der Benutzer sich mit der richtigen E-Mail-Adresse anmeldet","Öffne (falls Administrator) `control userpasswords2` oder Einstellungen → Konten — welcher Kontotyp ist konfiguriert?"],"loesung":"- Falls PIN nicht akzeptiert: „Ich habe meine PIN vergessen\\" auf der Anmeldeseite verwenden → Passwort-Reset über Microsoft-Konto\\n  - Falls Anmeldeinformationen inkonsistent: Credential Manager öffnen (`control keymgr.dll`) und Einträge für das betroffene Konto entfernen\\n  - Falls Kontotyp falsch: Erst lokales Konto erstellen und dann unter Einstellungen → Konten in Microsoft-Konto umwandeln","praevention":"Vor Kontotyp-Wechsel sicherstellen, dass der Benutzer das aktuelle Passwort kennt und Zugriff auf die hinterlegte E-Mail-Adresse hat\\n\\n---"},{"titel":"Deinstallierte Updates kommen wieder zurück","symptom":"Ein Update wurde deinstalliert, installiert sich nach Neustart erneut automatisch","ursache":"Windows Update hält das Update für erforderlich (besonders Sicherheitsupdates), oder ein Schadspiel des Update-Diensts","diagnose_schritte":["Prüfe den Update-Verlauf — ist das Update tatsächlich deinstalliert?","Suche das KB-Artikelnummer des betroffenen Updates in der Microsoft-Dokumentation","Prüfe, ob eine Gruppenrichtlinie oder Windows Update for Business das Update erzwingt"],"loesung":"- Update mit dem Windows Update Troubleshooter zurückhalten: Einstellungen → System → Problembehandlung → Windows Update\\n  - Alternativ: PowerShell `wushowhide.diagcab` (Microsoft-Tool zum Ausblenden von Updates)\\n  - Bei Unternehmen: Windows Update for Business- oder WSUS-Konfiguration prüfen, ob Updates über IT-Richtlinien erzwungen werden","praevention":"Vor Deinstallation prüfen, ob das Update kritisch ist — Sicherheitsupdates sollte man nicht dauerhaft entfernen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was ist der schnellste Weg, um den Geräte-Manager in Windows 11 zu öffnen?","optionen":["`Win + R` → `devmgmt.msc`","`Win + X` → Geräte-Manager","Einstellungen → System → Info → Geräte-Manager","Alle oben genannten sind korrekt"],"antwort":3,"erklaerung":"Alle drei Wege öffnen den Geräte-Manager."},{"nummer":2,"frage":"Welcher Kontotyp in Windows 11 ist für unternehmensverwaltete Geräte mit Intune am besten geeignet?","optionen":["Lokales Konto","Microsoft-Konto","Azure AD / Microsoft Entra ID","Gastkonto"],"antwort":2,"erklaerung":"Azure AD / Microsoft Entra ID ermöglicht zentrale Verwaltung durch den IT-Administrator."},{"nummer":3,"frage":"Ein Gerät im Geräte-Manager zeigt den Fehlercode 43. Was ist die wahrscheinlichste Ursache?","optionen":["Der Treiber ist nicht installiert oder beschädigt","Das Gerät ist deaktiviert","Der Netzwerkadapter hat kein Netzwerk-Kabel","Der Bildschirm ist defekt"],"antwort":0,"erklaerung":"Fehlercode 43 bedeutet, dass Windows das Gerät ordnungsgemäß erkennt, aber der Treiber meldet ein Problem."},{"nummer":4,"frage":"Was passiert bei einer Pausierung von Windows Updates für 5 Wochen?","optionen":["Alle Updates (inkl. Sicherheitsupdates) werden für 5 Wochen blockiert","Nur Funktionsupdates werden blockiert","Sicherheitsupdates werden weiterhin installiert, nur große Updates werden blockiert","Der PC wird für 5 Wochen nicht mehr neu gestartet"],"antwort":0,"erklaerung":"Die Pausierung blockiert alle Arten von Updates für den gewählten Zeitraum (maximal 5 Wochen)."},{"nummer":5,"frage":"Warum sind digitale Treibersignaturen in Windows 11 (64-Bit) wichtig?","optionen":["Sie verhindern, dass Treiber deinstalliert werden","Sie garantieren, dass der Treiber von Microsoft validiert wurde und kein Schadcode enthält","Sie machen Treiber schneller","Sie sind nur für Windows Home relevant"],"antwort":1,"erklaerung":"Signierte Treiber wurden durch Microsoft-Validierung (WHQL) geprüft und garantieren Integrität."}],"ticket":[{"situation":"Eine Mitarbeiterin meldet sich: „Seit dem Update gestern Abend funktioniert mein Drucker nicht mehr. Windows hat etwas installiert und seitdem kommt die Fehlermeldung, dass der Treiber nicht kompatibel sei. Ich muss heute dringend Verträge ausdrucken.\\"","aufgabe":"1. Wie priorisierst du das Ticket?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP2 (Hoch) — Drucker ist betriebskritisch, es gibt einen Workaround (z. B. PDF erstellen und auf einem anderen Gerät drucken). Kein kompletter Ausfall.\\n\\n**2. Diagnose:**\\n- Geräte-Manager öffnen und Druckerkategorie prüfen — gibt es einen Fehlercode?\\n- Treibereigenschaften öffnen: Wer ist der Anbieter? Wann wurde er installiert? Gibt es einen Hinweis auf Fehlercode 43 oder 10?\\n- Windows Update-Verlauf prüfen: Welches Update wurde „gestern Abend\\" installiert? Ist es ein Treiber-Update?\\n- Prüfen, ob es einen Systemwiederherstellungspunkt vor dem Update gibt.\\n\\n**3. Lösung:**\\n- **Schnellste Lösung:** Treiber zurücksetzen — Geräte-Manager → Drucker → Rechtsklick → Eigenschaften → Reiter „Treiber\\" → „Treiber zurücksetzen\\"\\n- **Alternativ:** Letzten funktionierenden Treiber manuell von der Hersteller-Website installieren\\n- **Workaround:** Dokumente als PDF exportieren und von einem druckfähigen Gerät aus drucken (z. B. anderer PC, Kopierer)\\n- **Falls fehlgeschlagen:** Systemwiederherstellung zum letzten funktionierenden Wiederherstellungspunkt\\n\\n**4. Dokumentation:**\\n- Problem: Drucker funktioniert nach Windows Update nicht mehr (Fehlercode 43)\\n- Ursache: Kompatibilitätsproblem zwischen aktuellem Treiber und Windows Update-KB [Nummer]\\n- Lösung: Treiber zurücksetzen auf vorherige Version\\n- Verifizierung: Testdruck erfolgreich durchgeführt\\n- Wissensdatenbank-Artikel: „Drucker-Probleme nach Windows Update — Treiber zurücksetzen\\"\\n\\n---"}],"slug":"modul-3-windows-11"},{"title":"Modul 4: Troubleshooting-Methodik — Fragen, Eingrenzen, Dokumentieren","level":1,"module":4,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.comptia.org/content/guides/comptia-a-plus-220-1102-exam-objectives","abrufdatum":"2026-10-19"},{"url":"https://www.coursera.org/professional-certificates/google-it-support","abrufdatum":"2026-10-19"},{"url":"https://www.coursera.org/learn/technical-support-fundamentals","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/windows-commands","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Das Problem nicht richtig identifiziert","symptom":"Du löst ein Problem, das der Nutzer nicht hatte — das eigentliche Problem bleibt bestehen","ursache":"Zu schnelle Hypothesen ohne gründliche Fragestellung; Annahmen statt Fakten","diagnose_schritte":["Lies das Ticket noch einmal — hat der Nutzer alle Informationen gegeben?","Reproduziere das Problem selbst (sofern möglich)","Vergleiche: Hast du das beschriebene Symptom oder nur deine Interpretation gesehen?"],"loesung":"- Stelle eine offene Rückfrage: \\"Um sicherzugehen: Wenn Sie auf X klicken, erscheint Y — korrekt?\\"\\n  - Dokumentiere das genaue Symptom in den Worten des Nutzers\\n  - Erst dann Theorie aufstellen","praevention":"Niemals mit Schritt 2 beginnen, bevor Schritt 1 (Problem identifizieren) abgeschlossen ist\\n\\n---"},{"titel":"Zu viele Änderungen gleichzeitig","symptom":"Nach dem \\"Fix\\" funktioniert ein anderes Feature nicht mehr","ursache":"Mehrere Lösungen auf einmal angewendet, ohne zu wissen, welche gewirkt hat","diagnose_schritte":["Liste alle durchgeführten Änderungen chronologisch auf","Prüfe, welche Änderung Seiteneffekte haben könnte","Mache die letzte Änderung rückgängig und teste"],"loesung":"- Änderungen auf einmal rückgängig machen oder\\n  - Systemwiederherstellungs-Punkt nutzen (falls vorhanden)","praevention":"Eine Änderung pro Schritt, testen, dann erst die nächste Änderung\\n\\n---"},{"titel":"Die Theorie nicht widerlegt, sondern bestätigt","symptom":"Du verfolgst eine Vermutung, obwohl die Gegentheorie wahrscheinlicher ist","ursache":"Bestätigungsfehler (Confirmation Bias) — du suchst nach Belegen für deine Theorie","diagnose_schritte":["Formuliere die Gegentheorie explizit: \\"Wenn nicht X, dann Y\\"","Suche aktiv nach Belegen, die deine Theorie widerlegen","Wenn alle Befunde zu deiner Theorie passen, aber das Problem bleibt → Theorie war unvollständig"],"loesung":"- Theorie neu aufstellen mit allen gesammelten Befunden\\n  - Perspektive wechseln: Was wäre, wenn die Ursache ganz woanders liegt?","praevention":"Die stärkste Theorie testen, die am wenigsten Annahmen benötigt\\n\\n---"},{"titel":"Keine Dokumentation der Lösung","symptom":"Das gleine Problem tritt eine Woche später wieder auf — niemand weiss, was gemacht wurde","ursache":"Lösung wurde nur telefonisch kommuniziert, nicht im Ticket dokumentiert","diagnose_schritte":["Prüfe, ob die Lösung im Ticket vermerkt ist","Prüfe, ob es einen Wissensdatenbank-Eintrag gibt","Frage dich: \\"Könnte ein Kollege mithilfe der Dokumentation das Problem lösen?\\""],"loesung":"- Ticket nachträglich mit allen Schritten aktualisieren\\n  - Wissensdatenbank-Eintrag erstellen\\n  - Team-Information (z. B. kurze E-Mail) versenden","praevention":"Dokumentation ist Teil der Lösung, keine Option — erst dann Ticket schliessen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Welcher ist der erste Schritt im systematischen Troubleshooting nach CompTIA A+?","optionen":["Eine Theorie aufstellen","Das Problem identifizieren","Eine Lösung umsetzen","Das System neu starten"],"antwort":1,"erklaerung":"Das Problem identifizieren. Ohne klare Identifizierung löst du unter Umständen das falsche Problem."},{"nummer":2,"frage":"Was ist \\"Divide and Conquer\\" im Troubleshooting?","optionen":["Mehrere Techniker an ein Problem setzen","Das Problem in kleinere Teilbereiche aufteilen und isolieren","Zwei Systeme gegeneinander testen","Das System in zwei Partitionen aufteilen"],"antwort":1,"erklaerung":"Das Problem wird in kleinere, testbare Bereiche aufgeteilt, um die Ursache zu isolieren."},{"nummer":3,"frage":"Welche Frage ist eine offene Frage für die erste Diagnose?","optionen":["\\"Ist der Drucker eingeschaltet?\\"","\\"Was genau passieren, wenn Sie auf \'Drucken\' klicken?\\"","\\"Haben Sie schon neu gestartet?\\"","\\"Tritt das Problem auf jedem PC auf?\\""],"antwort":1,"erklaerung":"Offene Fragen beginnen mit \\"Was\\", \\"Wie\\", \\"Wann\\" und geben dem Nutzer Raum für Beschreibungen."},{"nummer":4,"frage":"Warum solltest du nie mehrere Änderungen gleichzeitig vornehmen?","optionen":["Weil das zu langsam ist","Weil du nicht weisst, welche Änderung gewirkt hat, wenn etwas schiefgeht","Weil das System überhitzt","Weil das gegen die Lizenzbedingungen verstösst"],"antwort":1,"erklaerung":"Ohne isolierte Änderungen kann die Ursache von Nebenwirkungen nicht bestimmt werden."},{"nummer":5,"frage":"Wann ist ein Problem offiziell als \\"gelöst\\" zu dokumentieren?","optionen":["Sobald du die Lösung umgesetzt hast","Sobald der Nutzer bestätigt, dass das System wieder voll funktionsfähig ist","Sobald du das Ticket geschlossen hast","Sobald du eine Theorie aufgestellt hast"],"antwort":1,"erklaerung":"Erst nach Nutzer-Verifizierung und vollständiger Funktion ist das Problem gelöst."}],"ticket":[{"situation":"Eine Mitarbeiterin aus der Buchhaltung meldet sich: \\"Seit dem Windows-Update gestern Abend startet mein PC viel langsam. Normalerweise geht es in 30 Sekunden, jetzt dauert es über 3 Minuten. Und wenn er endlich startet, ist die Tastatur manchmal 10 Sekunden lang nicht reaktiv.\\"","aufgabe":"1. Identifiziere das Problem (Was genau ist das Symptom?)\\n2. Stelle 3 gezielte Fragen zur Eingrenzung\\n3. Beschreibe 2 Eingrenzungstests (Divide and Conquer)\\n4. Welche Tools würdest du nutzen? (Windows 11 23H2)\\n5. Dokumentiere den Fall","loesung":"**1. Problem identifizieren:**\\n- Sehr langer Boot-Prozess (30 Sek. → 3 Min.)\\n- Tastatur reagiert nach dem Start verzögert (ca. 10 Sek.)\\n- Korrelation mit Windows-Update (Temporalität)\\n\\n**2. Gezielte Fragen:**\\n- \\"Welches Update wurde installiert? (Einstellungen → Windows Update → Update-Verlauf)\\"\\n- \\"Gibt es Fehlermeldungen oder Bluescreens beim Start?\\"\\n- \\"Tritt das Problem auch im abgesicherten Modus auf?\\"\\n\\n**3. Eingrenzungstests:**\\n- **Test A (Boot-Diagnose):** `msconfig` → \\"Dienststart\\" → alle Nicht-Microsoft-Dienste deaktivieren, neu starten. Funktioniert es schnell? → Problem liegt an Drittanbieter-Dienst.\\n- **Test B (Update prüfen):** Einstellungen → Windows Update → Update-Verlauf → \\"Updates deinstallieren\\" (falls bekannt, welches Update). Danach: langsamer Start?\\n\\n**4. Tools:**\\n- `eventvwr.msc` → Windows-Protokolle → System → Filterung nach \\"Fehler\\" und \\"Warnung\\" rund um die Boot-Zeit\\n- Task-Manager → Registerkarte \\"Start\\" → Start-Auswirkung prüfen (hohe Werte?)\\n- `msconfig` → Start deaktivieren/ausschalten\\n- Geräte-Manager → Tastatur-Treiber aktualisieren/installieren (falls nach Update defekt)\\n\\n**5. Dokumentation:**\\n- Problem: Langsamer Boot + Tastatur-Verzögerung nach Windows-Update\\n- Diagnose: Boot-Zeiten geprüft, Event Viewer analysiert, msconfig getestet\\n- Theorie: Update verursacht Treiber-/Start-Problem\\n- Lösung: [abhängig vom Test — z. B. Problematiches Update deinstallieren, Tastatur-Treiber aktualisieren]\\n- Verifizierung: Boot-Zeit normal, Tastatur sofort reaktiv\\n- Prävention: Updates auf einem Testsystem vor Rollout validieren\\n\\n---"}],"slug":"modul-4-troubleshooting"},{"title":"Modul 5: Netzwerk-Basics — IP, DHCP, DNS, WLAN, ipconfig/ping/tracert","level":1,"module":5,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.scribd.com/document/943128131/Comptia-a-Plus-220-1101-Exam-Objectives-1-1","abrufdatum":"2026-10-19"},{"url":"https://www.oreilly.com/library/view/comptia-a-core/9780137637775/ch10.xhtml","abrufdatum":"2026-10-19"},{"url":"https://www.professormesser.com/free-a-plus-training/220-1101/220-1101-video/220-1101-training-course/","abrufdatum":"2026-10-19"},{"url":"https://www.netacad.az/en/networking-basics/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/troubleshoot-premises-hybrid-networking/4-diagnose-ip-configuration-issues","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/trace-route-troubleshoot-tcp-ip-problems","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-server/networking/dns/troubleshoot/troubleshoot-dns-client","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"APIPA-Adresse (169.254.x.x) — DHCP-Server nicht erreichbar","symptom":"`ipconfig` zeigt `169.254.x.x`, kein Internetzugang","ursache":"DHCP-Server nicht erreichbar (Router aus, Kabel DHCP deaktiviert, Client falsch konfiguriert)","diagnose_schritte":["`ipconfig /all` — prüfen, ob `DHCP Enabled: Yes` ist","`ping <Gateway>` — Router erreichbar?","`ipconfig /release` und `ipconfig /renew` — Lease neu anfordern","Router-Log prüfen (DHCP aktiviert? IP-Bereich verfügbar?)"],"loesung":"- DHCP am Router aktivieren\\n  - `ipconfig /renew` ausführen\\n  - Bei statischer Konfiguration: manuell gültige IP, Gateway, DNS eintragen","praevention":"DHCP-Server-Verfügbarkeit überwachen; statische IPs für kritische Geräte mit Reservierung\\n\\n---"},{"titel":"Ping funktioniert, aber Browser zeigt \\"Keine Verbindung","symptom":"`ping 8.8.8.8` funktioniert, aber Webseiten laden nicht","ursache":"DNS-Auflösung fehlgeschlagen, Proxy falsch konfiguriert, oder Blockade auf Anwendungsebene","diagnose_schritte":["`ping www.example.com` — funktioniert DNS?","`nslookup www.example.com` — manuelle DNS-Abfrage testen","`ipconfig /all` — DNS-Server korrekt?","`ipconfig /flushdns` — Cache leeren","`netsh winhttp show proxy` — Proxy-Einstellung prüfen"],"loesung":"- DNS-Server manuell setzen (z. B. 8.8.8.8 / 1.1.1.1)\\n  - `ipconfig /flushdns` ausführen\\n  - Proxy-Einstellungen in Windows zurücksetzen","praevention":"DNS-Server-Redundanz (primär + sekundär), regelmäßige Cache-Pflege\\n\\n---"},{"titel":"Ping schlägt fehl, obwohl Verbunden-Anzeige","symptom":"WLAN zeigt \\"Verbunden\\", aber `ping <Gateway>` schlägt fehl","ursache":"Falsche Subnetzmaske/Gateway, IP-Konflikt, oder Adapter deaktiviert","diagnose_schritte":["`ipconfig /all` — IP, Subnetzmaske, Gateway prüfen","`ping <eigene IP>` — Adapter funktioniert?","`arp -a` — MAC-Adresse des Gateways sichtbar?","`netsh interface show interface` — Adapter-Status"],"loesung":"- Adapter deaktivieren/aktivieren\\n  - `netsh int ip reset` und `netsh winsock reset` (als Admin)\\n  - IP-Konflikt: `ipconfig /release` → Router-Neustart → `ipconfig /renew`","praevention":"Reservierungen für statische Geräte, IP-Adressmanagement dokumentieren\\n\\n---"},{"titel":"tracert stoppt früh — Router blockiert ICMP","symptom":"`tracert` zeigt nur 1–2 Hops, dann `* * *`, Ziel ist aber erreichbar","ursache":"Zwischen-Router blockiert ICMP (häufig aus Sicherheitsgründen), oder Firewall","diagnose_schritte":["`ping <Ziel>` — ist das Ziel per Ping erreichbar?","`tracert -d` — ohne DNS-Lookup erneut versuchen","Vergleich: anderes Gerät im selben Netzwerk","`pathping <Ziel>` — alternative Tool (kombiniert ping + tracert)"],"loesung":"- Nicht als Fehler werten, wenn Ping und Anwendung funktionieren\\n  - `pathping` verwenden für detailliertere Analyse\\n  - Port-basierte Tests (z. B. `telnet <host> 80`) als Alternative","praevention":"ICMP-Blockade ist legitime Sicherheitsmaßnahme; auf Alternativen zurückgreifen\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Was bedeutet es, wenn `ipconfig` die IP-Adresse `169.254.10.50` anzeigt?","optionen":["Der DHCP-Server hat diese Adresse vergeben","Windows hat eine APIPA-Adresse vergeben, weil kein DHCP-Server erreichbar war","Der Computer hat eine statische IP erhalten","Die Subnetzmaske ist falsch konfiguriert"],"antwort":1,"erklaerung":"APIPA (Automatic Private IP Addressing) im Bereich 169.254.0.0/16 zeigt einen DHCP-Fehler an."},{"nummer":2,"frage":"Welcher DNS-Datensatztyp wird verwendet, um eine Domain einer IPv4-Adresse zuzuordnen?","optionen":["AAAA","MX","A","TXT"],"antwort":2,"erklaerung":"der A-Record (Address) mappt eine Domain auf eine IPv4-Adresse."},{"nummer":3,"frage":"Ein Benutzer meldet: \\"Mein WLAN zeigt \'Verbunden\', aber ich kann keine Webseiten öffnen. `ping 8.8.8.8` funktioniert.\\" Was ist die wahrscheinlichste Ursache?","optionen":["Defektes WLAN-Kabel","DNS-Auflösung fehlgeschlagen","Der WLAN-Treiber ist veraltet","Der Router hat keinen Strom"],"antwort":1,"erklaerung":"Ping auf IP-Ebene funktioniert, aber Domain-Auflösung schlägt fehl → DNS-Problem."},{"nummer":4,"frage":"Welcher Befehl zeigt die aktuelle TCP/IP-Konfiguration samt MAC-Adresse und DHCP-Server an?","optionen":["`ping /all`","`tracert /all`","`ipconfig /all`","`netstat /all`"],"antwort":2,"erklaerung":"`ipconfig /all` zeigt die vollständige Konfiguration aller Netzwerkadapter."},{"nummer":5,"frage":"Was zeigt der Befehl `tracert`?","optionen":["Die IP-Adresse des lokalen Computers","Den Weg (Hops/Router) zu einem Ziel und die Latenzzeit","Den Inhalt des DNS-Caches","Die physische Netzwerktopologie"],"antwort":1,"erklaerung":"tracert (Trace Route) zeigt jeden Router auf dem Weg zum Ziel."}],"ticket":[{"situation":"Ein Mitarbeiter aus dem Marketing meldet sich: \\"Seit dem Umzug in den neuen Raum habe ich kein Internet mehr. Das WLAN zeigt \'Verbunden\', aber alle Webseiten zeigen \'Keine Verbindung zum Internet\'. Meine Kollegen im selben Raum haben kein Problem.\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor? (Nutze die Bottom-up-Methode)\\n3. Was ist die wahrscheinlichste Ursache und wie löst du sie?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP2 (Hoch) — Einzelner Benutzer betroffen, aber vollständiger Verlust des Internetzugangs.\\n\\n**2. Diagnose (Bottom-up):**\\n1. `ipconfig /all` — prüfen: IP-Adresse, Subnetzmaske, Gateway, DNS-Server\\n2. `ping 127.0.0.1` — lokaler TCP/IP-Stack\\n3. `ping <Gateway>` — Router erreichbar?\\n4. `ping 8.8.8.8` — Internet per IP erreichbar?\\n5. `ping www.example.com` — DNS-Auflösung?\\n6. `tracert 8.8.8.8` — wo bricht die Verbindung ab?\\n\\n**3. Wahrscheinliche Ursache & Lösung:**\\n- **Ursache:** Der PC hat eine APIPA-Adresse (169.254.x.x) erhalten, weil der DHCP-Server im neuen Raum nicht erreichbar ist — z. B. weil der Patch-Port im neuen Raum nicht mit dem Switch verbunden ist oder ein anderer DHCP-Bereich gilt.\\n- **Lösung:**\\n  1. `ipconfig /release` und `ipconfig /renew` — versucht, eine gültige IP zu erhalten\\n  2. Falls weiterhin APIPA: Netzwerkverbindung des Workspace prüfen (Patch-Kabel, Switch-Port)\\n  3. Falls Switch-Port aktiv: IP manuell konfigurieren (IP aus richtigem Bereich, Gateway, DNS)\\n  4. Nach Behebung: `ipconfig /all` dokumentieren\\n- **Alternative:** Falls Kollegen im selben Raum funktionieren → defektes WLAN-Modul im PC oder Treiber-Problem → `netsh wlan show wlanreport` erstellen und analysieren\\n\\n**4. Dokumentation:**\\n- Problem: WLAN verbunden, kein Internet nach Raumumzug\\n- Ursache: DHCP-Server nicht erreichbar → APIPA-Adresse\\n- Diagnose: ipconfig /all → 169.254.x.x → Switch-Port geprüft → Patch-Kabel neu gesteckt\\n- Lösung: ipconfig /renew → gültige IP erhalten → Internetzugang wiederhergestellt\\n- Verifizierung: ping 8.8.8.8 → Erfolg; Browser → Webseite lädt\\n\\n---"}],"slug":"modul-5-netzwerk-basics"},{"title":"Modul 6: Microsoft 365 — Outlook, Teams Basics, Passwort-Resets","level":1,"module":6,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/en-us/training/paths/describe-microsoft-365-core-services-concepts/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/microsoft-365/admin/setup/setup-outlook?view=o365-worldwide","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/microsoftteams/teams-overview","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/microsoftteams/teams-channels-overview","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/reset-passwords?view=o365-worldwide","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/let-users-reset-passwords?view=o365-worldwide","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Administrator hat keine passende Rolle für Passwort-Reset","symptom":"Administrator-Konto meldet „Nicht autorisiert\\", obwohl es ein Admin-Konto ist","ursache":"Nicht jeder Administrator hat automatisch das Recht, Passwörter zurückzusetzen. Nur spezifische Rollen wie Password Administrator oder Global Administrator dürfen Passwörter zurücksetzen.","diagnose_schritte":["Prüfe im Microsoft 365 Admin Center unter **Benutzer** > **Aktive Benutzer** die zugewiesene Rolle","Vergleiche mit der Rollen-Tabelle in Abschnitt 4","Prüfe, ob die Rolle die Berechtigung „Passwort zurücksetzen\\" enthält"],"loesung":"- Weise dem Administrator die Rolle „Password Administrator\\" zu\\n  - Alternativ: Lass das Passwort von einem Global Administrator zurücksetzen","praevention":"Dokumentiere, welche Rollen welche Berechtigungen haben. Verweise auf die Microsoft Learn-Dokumentation zur Rollenverteilung.\\n\\n---"},{"titel":"SSPR funktioniert nicht für Benutzer","symptom":"Benutzer können ihr Passwort nicht selbst zurücksetzen, obwohl SSPR aktiviert ist","ursache":"SSPR ist nicht für alle Benutzer aktiviert oder es fehlt eine Authentifizierungsmethode","diagnose_schritte":["Prüfe im Microsoft Entra Admin Center, ob SSPR auf „Alle\\" oder „Ausgewählt\\" gestellt ist","Prüfe, ob die Benutzer in der ausgewählten Gruppe enthalten sind","Prüfe, ob für die Benutzer eine Authentifizierungsmethode (E-Mail, Telefon) konfiguriert ist"],"loesung":"- Aktiviere SSPR für alle Benutzer oder füge die betroffenen Benutzer der Gruppe hinzu\\n  - Weise eine Authentifizierungsmethode zu (z. B. E-Mail oder Mobiltelefonnummer)","praevention":"SSPR bei der Einführung direkt für alle Benutzer aktivieren und Authentifizierungsmethoden im Onboarding-ProzessPflicht machen.\\n\\n---"},{"titel":"Outlook fragt nach Passwort-Reset weiterhin nach Passwort","symptom":"Nach erfolgreichem Passwort-Reset fragt Outlook wiederholt nach dem Passwort, auch wenn es korrekt eingegeben wird","ursache":"Der Windows Credential Manager speichert die alten Anmeldeinformationen","diagnose_schritte":["Prüfe, ob der Benutzer im Active Directory das korrekte Passwort hat","Öffne den Credential Manager (Systemsteuerung > Benutzerkonten > Credential Manager)","Suche nach Einträgen, die auf Outlook/Exchange verweisen"],"loesung":"- Credential Manager öffnen und die betroffenen Einträge entfernen\\n  - Outlook neu starten — es sollte nach dem neuen Passwort fragen","praevention":"Schulung für Benutzer: Nach Passwortänderung auch Credential Manager prüfen. Alternative: Gruppenrichtlinie zur automatischen Aktualisierung konfigurieren.\\n\\n---"},{"titel":"Teams-Kanäle falsch angelegt","symptom":"Benutzer können Dateien nicht teilen oder haben zu viel/zugriff auf vertrauliche Kanäle","ursache":"Falsche Kanal-Typen (Standard vs. Privat) oder fehlende Verständnis der Sichtbarkeitsregeln","diagnose_schritte":["Prüfe im Teams Admin Center die Kanal-Einstellungen","Prüfe, wer auf den Kanal zugreifen kann","Vergleiche mit den gewünschten Zugriffsrichtlinien"],"loesung":"- Erstelle einen privaten Kanal für vertrauliche Themen\\n  - Dokumentiere die Sichtbarkeitsregeln für jeden Kanal-Typ\\n  - Entferne unnötige Berechtigungen","praevention":"Erstelle eine Richtlinie für Kanal-Typen. Standardmäßig Standardkanäle nur für allgemeine Themen, private Kanäle nur für sensible Projekte.\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Welche Rolle benötigt ein Administrator, um Passwörter zurückzusetzen?","optionen":["Teams Administrator","Password Administrator oder Global Administrator","SharePoint Administrator","Exchange Administrator"],"antwort":1,"erklaerung":"Nur Password Administrator oder höhere Rollen dürfen Passwörter zurücksetzen."},{"nummer":2,"frage":"Was wird beim Erstellen eines Teams automatisch erstellt?","optionen":["Nur ein SharePoint","Eine Microsoft 365-Gruppe, SharePoint-Site, Exchange-Postfach und OneNote-Notizbuch","Nur ein Exchange-Postfach","Ein lokaler Active Directory-Benutzer"],"antwort":1,"erklaerung":"Teams basiert auf Microsoft 365-Gruppen und erstellt automatisch die zugehörigen Ressourcen."},{"nummer":3,"frage":"Wo kann ein Administrator in Microsoft 365 ein Benutzerpasswort zurücksetzen?","optionen":["Teams Admin Center","SharePoint Admin Center","Microsoft 365 Admin Center > Benutzer > Aktive Benutzer","OneDrive Admin Center"],"antwort":2,"erklaerung":"Das Microsoft 365 Admin Center unter „Benutzer > Aktive Benutzer\\" ist der richtige Ort."},{"nummer":4,"frage":"Was bedeutet SSPR?","optionen":["Secure System Password Recovery","Self-Service Password Reset","Single Sign-On Password Reset","System Service Protection Reset"],"antwort":1,"erklaerung":"Self-Service Password Reset. Benutzer können ihr Passwort selbst zurücksetzen."},{"nummer":5,"frage":"Warum kann Outlook nach einer Passwortänderung weiterhin das alte Passwort verlangen?","optionen":["Outlook ist defekt","Der Credential Manager speichert alte Anmeldeinformationen","Der E-Mail-Server ist offline","Das Konto wurde gelöscht"],"antwort":1,"erklaerung":"Der Windows Credential Manager speichert die alten Anmeldeinformationen."}],"ticket":[{"situation":"Ein Mitarbeiter meldet sich bei dir: „Ich habe gestern mein Passwort geändert, seitdem funktioniert Outlook nicht mehr. Ich bekomme ständig eine Aufforderung, mein Passwort einzugeben, aber wenn ich es eingebe, erscheint wieder die Fehlermeldung. Ich muss dringend E-Mails beantworten. Außerdem muss ich für ein neues Projekt ein Team in Microsoft Teams erstellen — wie geht das?\\"","aufgabe":"1. Priorisiere das Ticket\\n2. Diagnose das Outlook-Problem\\n3. Löse das Problem\\n4. Erkläre, wie der Benutzer ein neues Team in Microsoft Teams erstellt\\n5. Dokumentiere den Fall für die Wissensdatenbank","loesung":"**1. Priorität:**\\nP2 (Hoch) — E-Mail ist betriebskritisch, aber es gibt einen Workaround (Outlook im Web).\\n\\n**2. Diagnose:**\\n- Prüfe, ob der Benutzer im Microsoft Entra ID das korrekte Passwort hat\\n- Prüfe, ob das Passwort im Microsoft 365 Admin Center korrekt gespeichert ist\\n- Prüfe, ob Outlook den Cached Exchange Mode verwendet (das alte Passwort ist im Cache gespeichert)\\n- Prüfe, ob der Benutzer das Passwort in Windows aktualisiert hat (Credential Manager)\\n\\n**3. Lösung:**\\n- Credential Manager öffnen (Systemsteuerung > Benutzerkonten > Credential Manager)\\n- Gespeicherte Anmeldeinformationen für Outlook/Exchange finden und entfernen\\n- Outlook neu starten — es sollte nach dem neuen Passwort fragen\\n- Alternative: `control keymgr.dll` ausführen, um den Credential Manager direkt zu öffnen\\n\\n**4. Teams-Erstellung:**\\n- In Microsoft Teams auf „Teams beitreten oder erstellen\\" klicken\\n- „Team erstellen\\" wählen\\n- Vorlage auswählen (z. B. „Standard\\" oder „Projekt\\")\\n- Team-Namen eingeben und Beschreibung hinzufügen\\n- Sichtbarkeit festlegen (Öffentlich oder Privat)\\n- Mitglieder hinzufügen\\n\\n**5. Dokumentation:**\\n- Problem: Passwort-Change → Outlook fragt wiederholt nach Passwort\\n- Ursache: Altes Passwort im Windows Credential Manager gespeichert\\n- Lösung: Credential Manager → Windows-Anmeldeinformationen → Outlook-Eintrag entfernen\\n- Verifizierung: Outlook startet ohne Passwort-Aufforderung\\n\\n---"}],"slug":"modul-6-m365"},{"title":"Modul 7: Sicherheit Basics — Defender, Phishing, MFA, Fernwartung","level":1,"module":7,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://www.comptia.org/en-us/blog/how-to-study-for-comptia-a/","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/security/operating-system-security/system-security/windows-defender-security-center/windows-defender-security-center","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/defender-endpoint/microsoft-defender-security-center-antivirus","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/securing-you-basics-beyond/2-phishing","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/remotepc/remote-desktop-allow-access","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/security/operating-system-security/system-security/windows-defender-security-center/wdsc-firewall-network-protection","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Echtzeit-Schutz deaktiviert","symptom":"Viren werden nicht erkannt, System wird infiziert","ursache":"Echtzeit-Schutz wurde manuell deaktiviert oder durch Drittanbieter-Antivirus","diagnose_schritte":["Windows Security → Virus & threat protection → Einstellungen verwalten","Prüfen, ob \\"Echtzeit-Schutz\\" aktiviert ist","Prüfen, ob ein Drittanbieter-Antivirus installiert ist"],"loesung":"- Echtzeit-Schutz wieder aktivieren\\n  - Drittanbieger-Antivirus deinstallieren oder konfigurieren","praevention":"Echtzeit-Schutz nie dauerhaft deaktivieren; bei Problemen temporär deaktivieren und danach sofort wieder aktivieren\\n\\n---"},{"titel":"Phishing-E-Mail angeklickt","symptom":"Benutzer hat auf einen Link in einer verdächtigen E-Mail geklickt","ursache":"Fehlende Sensibilisierung, E-Mail sah vertrauenswürdig aus","diagnose_schritte":["Prüfen, ob der Benutzer Anhänge geöffnet oder Links angeklickt hat","Prüfen, ob das Passwort eingegeben wurde","System auf Malware scannen"],"loesung":"- Passwort sofort ändern\\n  - MFA aktivieren falls noch nicht geschehen\\n  - System mit Microsoft Defender Antivirus vollständig scannen\\n  - IT-Sicherheitsteam informieren","praevention":"Regelmäßige Schulungen, Phishing-Simulationen, \\"Melden\\"-Button in Outlook nutzen\\n\\n---"},{"titel":"Firewall deaktiviert","symptom":"Netzwerkverbindungen werden nicht gefiltert, System ist angreifbar","ursache":"Firewall wurde deaktiviert, um eine App zum Laufen zu bringen","diagnose_schritte":["Windows Security → Firewall & Netzwerkschutz","Prüfen, ob die Firewall für das aktuelle Netzwerkprofil aktiviert ist"],"loesung":"- Firewall wieder aktivieren\\n  - Stattdessen eine Ausnahmeregel für die betreffende App erstellen","praevention":"Firewall nie komplett deaktivieren; immer Ausnahmeregeln verwenden\\n\\n---"},{"titel":"Remote Desktop ohne Sicherheitsmaßnahmen","symptom":"Remote Desktop ist aktiviert, aber nicht abgesichert","ursache":"Remote Desktop wurde ohne starke Passwörter oder NLA aktiviert","diagnose_schritte":["Prüfen, ob Remote Desktop aktiviert ist","Prüfen, ob NLA aktiviert ist","Prüfen, welche Benutzer Zugriff haben"],"loesung":"- NLA aktivieren\\n  - Starke Passwörter für alle Remote-Benutzer festlegen\\n  - MFA konfigurieren\\n  - Remote Desktop nur in vertrauenswürdigen Netzwerken aktivieren","praevention":"Remote Desktop nur bei Bedarf aktivieren, regelmäßig überwachen, Zugriffsrechte einschränken\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Wo findest du die Einstellungen für Microsoft Defender Antivirus in Windows 11?","optionen":["Systemsteuerung → Programme","Windows Security → Virus & threat protection","Einstellungen → System → Info","Task-Manager → Start"],"antwort":1,"erklaerung":"Windows Security → Virus & threat protection."},{"nummer":2,"frage":"Welches ist ein typisches Erkennungsmerkmal für Phishing-E-Mails?","optionen":["Die E-Mail kommt von einem bekannten Kollegen","Die E-Mail enthält eine dringende Aufforderung und einen verdächtigen Link","Die E-Mail ist in einer Fremdsprache verfasst","Die E-Mail hat kein Betreff"],"antwort":1,"erklaerung":"Dringlichkeit und verdächtige Links sind klassische Phishing-Merkmale."},{"nummer":3,"frage":"Was bedeutet MFA?","optionen":["Multi-Firewall-Activation","Multi-Factor Authentication","Managed File Access","Microsoft Firewall App"],"antwort":1,"erklaerung":"Multi-Factor Authentication."},{"nummer":4,"frage":"Welche Windows-Edition kann NICHT als Remote-Desktop-Host dienen?","optionen":["Windows 11 Pro","Windows 11 Enterprise","Windows 11 Home","Windows 11 Education"],"antwort":2,"erklaerung":"Windows 11 Home kann nicht als Remote-Desktop-Host dienen."},{"nummer":5,"frage":"Was solltest du tun, wenn du eine verdächtige E-Mail erhältst?","optionen":["Auf den Link klicken, um zu prüfen","Die E-Mail an alle Kollegen weiterleiten","Nicht klicken, die E-Mail melden und löschen","Die E-Mail ignorieren und nichts tun"],"antwort":2,"erklaerung":"Nicht klicken, melden und löschen."}],"ticket":[{"situation":"Ein Mitarbeiter meldet sich: \\"Ich habe heute Morgen eine E-Mail erhalten, die aussieht, als wäre sie von unserer IT-Abteilung. Darin stand, dass mein Passwort abgelaufen ist und ich es über einen Link ändern muss. Ich habe auf den Link geklickt und meine Daten eingegeben. Jetzt habe ich Angst, dass mein Konto kompromittiert ist.\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP1 (Kritisch) — Möglicherweise kompromittiertes Konto, Gefahr für gesamtes Netzwerk.\\n\\n**2. Diagnose:**\\n- Prüfen, ob der Benutzer tatsächlich Daten eingegeben hat\\n- Prüfen, ob das Konto ungewöhnliche Aktivitäten zeigt (Active Directory / Microsoft Entra ID)\\n- Prüfen, ob der Benutzer auf weitere Links geklickt oder Anhänge geöffnet hat\\n- System des Benutzers auf Malware scannen\\n\\n**3. Lösung:**\\n- Passwort des Benutzers sofort zurücksetzen\\n- MFA für das Konto aktivieren (falls nicht bereits geschehen)\\n- Alle aktiven Sitzungen des Benutzers beenden\\n- System mit Microsoft Defender Antivirus vollständig scannen\\n- IT-Sicherheitsteam informieren\\n- Benutzer über Phishing aufklären\\n\\n**4. Dokumentation:**\\n- Problem: Benutzer hat Phishing-E-Mail angeklickt und Daten eingegeben\\n- Ursache: Fehlende Sensibilisierung, E-Mail sah vertrauenswürdig aus\\n- Lösung: Passwort zurückgesetzt, MFA aktiviert, System gescannt\\n- Verifizierung: Keine weiteren Anomalien, Benutzer geschult\\n- Prävention: Regelmäßige Schulungen, Phishing-Simulationen\\n\\n---"}],"slug":"modul-7-sicherheit"},{"title":"Modul 8: Remote-Support-Tools und Benutzer-Kommunikation","level":1,"module":8,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/en-us/windows-server/remote/remote-desktop-services/clients/remote-desktop-clients","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/windows/win32/termserv/remote-desktop-protocol","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/content/guides/comptia-a-220-1102-exam-objectives","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/en-us/training/modules/introduction-to-remote-desktop/","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"RDP ohne Network Level Authentication (NLA)","symptom":"Unbefugte Personen können auf den Remote-PC zugreifen","ursache":"NLA wurde deaktiviert, sodass die Authentifizierung erst nach der Verbindung erfolgt","diagnose_schritte":["Öffne Systemsteuerung → System → Remotedesktop","Prüfe, ob \\"Verbindungen nur von Computern mit Remotedesktop mit Network Level Authentication zulassen\\" aktiviert ist","Prüfe die Windows-Firewall-Regeln für RDP (Port 3389)"],"loesung":"- NLA aktivieren (Systemsteuerung → System → Remotedesktop → Erweiterte Einstellungen)\\n  - RDP-Zugriff auf ein Minimum von Benutzern beschränken\\n  - VPN oder RD-Gateway für externe Zugriffe verwenden","praevention":"NLA immer aktivieren, RDP nie direkt aus dem Internet zugänglichstellen\\n\\n---"},{"titel":"Remote-Support-Tool ohne Zustimmung des Benutzers","symptom":"Benutzer fühlt sich überwacht oder ausgeraubt","ursache":"Remote-Zugriff wurde ohne ausdrückliche Zustimmung oder ohne klare Kommunikation durchgeführt","diagnose_schritte":["Prüfe, ob der Benutzer den Zugriff ausdrücklich bestätigt hat","Prüfe, ob der Benutzer verstanden hat, was bedeutet","Prüfe, ob die Sitzung dokumentiert wurde"],"loesung":"- Sitzung beenden und den Benutzer um Entschuldigung bitten\\n  - Klare Erklärung des Zwecks der Sitzung geben\\n  - Zustimmung schriftlich oder im Ticket dokumentieren","praevention":"Immer vor der Sitzung erklären, was passiert, und Zustimmung einholen\\n\\n---"},{"titel":"Unverschlüsselte oder unsichere Verbindung","symptom":"Daten können abgehört werden, Verbindung wird getrennt","ursache":"Veraltete RDP-Version, keine TLS-Verschlüsselung, oder unsicheres Netzwerk","diagnose_schritte":["Prüfe die RDP-Version (Windows 10/11 verwenden standardmäßig TLS 1.2+)","Prüfe, ob die Verbindung über ein öffentliches WLAN läuft","Prüfe, ob ein VPN verwendet wird"],"loesung":"- VPN für alle externen Verbindungen verwenden\\n  - RDP-Gateway (RD-Gateway) einsetzen\\n  - Quick Assist oder andere Tools mit Ende-zu-Ende-Verschlüsselung verwenden","praevention":"Niemals unverschlüsselte Verbindungen über öffentliche Netzwerke verwenden\\n\\n---"},{"titel":"Keine Dokumentation der Remote-Sitzung","symptom":"Kollege weiß nicht, was während der Sitzung gemacht wurde","ursache":"Sitzung wurde nicht dokumentiert oder aufgezeichnet","diagnose_schritte":["Prüfe, ob die Sitzung im Ticket dokumentiert wurde","Prüfe, ob eine Aufzeichnung vorhanden ist","Prüfe, ob alle Änderungen im System nachvollziehbar sind"],"loesung":"- Sitzung im Ticket dokumentieren (Datum, Uhrzeit, Dauer, durchgeführte Schritte)\\n  - Aufzeichnung der Sitzung speichern (falls das Tool dies unterstützt)\\n  - Änderungen im System protokollieren (z. B. geänderte Einstellungen)","praevention":"Vor jeder Remote-Sitzung eine Checkliste verwenden:\\n  - [ ] Zustimmung des Benutzers eingeholt\\n  - [ ] Zweck der Sitzung erklärt\\n  - [ ] Sitzung dokumentiert\\n  - [ ] Änderungen protokolliert\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Welches Tool ist in allen Windows 11-Editionen verfügbar und erfordert keine Installation?","optionen":["Remotedesktop (RDP)","Quick Assist","VNC","TeamViewer"],"antwort":1,"erklaerung":"Quick Assist ist in Windows 10 und 11 integriert und funktioniert in allen Editionen."},{"nummer":2,"frage":"Was bedeutet NLA im Kontext von RDP?","optionen":["Network Level Authentication","Network Login Access","New Local Account","Network License Agreement"],"antwort":0,"erklaerung":"Network Level Authentication. NLA verlangt Authentifizierung bevor eine RDP-Verbindung hergestellt wird."},{"nummer":3,"frage":"Welches Problem kann NICHT remote gelöst werden?","optionen":["Eine Software installieren","Ein defektes Netzwerk-Kabel ersetzen","Eine Fehlkonfiguration korrigieren","Ein Virus-Scan durchführen"],"antwort":1,"erklaerung":"Hardware-Defekte erfordern einen Besuch vor Ort."},{"nummer":4,"frage":"Warum ist es wichtig, während einer Remote-Sitzung jeden Schritt zu erklären?","optionen":["Weil der Benutzer sonst die Verbindung trennt","Weil der Benutzer sieht, was du tust, und Transparenz Vertrauen schafft","Weil das Gesetz es vorschreibt","Weil der PC sonst langsamer wird"],"antwort":1,"erklaerung":"Der Benutzer sieht den Bildschirm. Erklärungen schaffen Transparenz und Vertrauen."},{"nummer":5,"frage":"Welches Protokoll verwendet RDP standardmäßig?","optionen":["HTTP","FTP","RDP (eigenes Protokoll auf TCP 3389)","SSH"],"antwort":2,"erklaerung":"RDP verwendet ein eigenes Protokoll auf TCP-Port 3389."}],"ticket":[{"situation":"Ein Mitarbeiter im Vertrieb meldet sich: \\"Ich bin heute im Homeoffice und kann nicht auf die Firmen-Cloud zugreifen. Ich bekomme immer die Fehlermeldung \'Verbindung zum Server fehlgeschlagen\'. Ich muss dringend auf die Kunden-Datenbank zugreifen, weil ich heute noch ein Angebot erstellen muss.\\"","aufgabe":"1. Was ist die Priorität dieses Tickets?\\n2. Wie gehst du bei der Diagnose vor?\\n3. Wie löst du das Problem?\\n4. Dokumentiere den Fall für die Wissensdatenbank.","loesung":"**1. Priorität:**\\nP2 (Hoch) — Der Mitarbeiter kann nicht arbeiten, aber es gibt einen Workaround (z. B. E-Mail auf dem Smartphone). Wenn mehrere Mitarbeiter betroffen sind, steigt die Priorität auf P1.\\n\\n**2. Diagnose:**\\n- Prüfe, ob das Problem nur bei diesem Mitarbeiter auftritt oder ob es ein allgemeines Problem ist\\n- Frage den Mitarbeiter, ob er sich im VPN befindet (falls Cloud-Zugriff VPN erfordert)\\n- Prüfe, ob der Mitarbeiter eine stabile Internetverbindung hat\\n- Prüfe, ob der Cloud-Dienst verfügbar ist (Status-Seite des Anbieters)\\n- Bitte den Mitarbeiter, einen Screenshot der Fehlermeldung zu senden\\n\\n**3. Lösung:**\\n- **Szenario A (VPN-Problem):** Bitte den Mitarbeiter, sich vom VPN zu trennen und neu zu verbinden. Falls das nicht hilft, VPN-Client neu starten.\\n- **Szenario B (Internetproblem):** Bitte den Mitarbeiter, die Internetverbindung zu prüfen (z. B. Router neu starten, Mobilfunk-Hotspot testen).\\n- **Szenario C (Cloud-Dienst ausgefallen):** Den Mitarbeiter über den Ausfall informieren und alternative Arbeitsvorschläge machen (z. B. lokale Dateien bearbeiten).\\n- **Szenario D (Konto gesperrt):** Prüfe im Active Directory, ob das Konto des Benutzers gesperrt ist. Falls ja, entsperren und neuen Passwort-Reset durchführen.\\n\\n**4. Dokumentation:**\\n- Problem: Kein Zugriff auf Firmen-Cloud aus dem Homeoffice\\n- Ursache: [je nach Szenario, z. B. VPN-Client nicht verbunden]\\n- Lösung: [je nach Szenario, z. B. VPN neu verbunden]\\n- Verifizierung: Mitarbeiter kann auf Cloud zugreifen\\n- Tipp für Benutzer: Immer prüfen, ob VPN aktiv ist, bevor man sich bei Cloud-Diensten anmeldet\\n\\n---"}],"slug":"modul-8-remote"},{"title":"Modul 9: Windows Tiefe — Ereignisanzeige, Registry, Dienste, Task-Manager, Performance","level":2,"module":9,"last_verified":"2026-10-19","windows_version":"Windows 11 23H2","sources":[{"url":"https://learn.microsoft.com/de-de/windows/win32/eventlog/event-viewer","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows/win32/sysinfo/registry","abrufdatum":"2026-10-19"},{"url":"https://learn.microsoft.com/de-de/windows/win32/services/services","abrufdatum":"2026-10-19"},{"url":"https://www.comptia.org/certifications/a","abrufdatum":"2026-10-19"}],"fehler":[{"titel":"Ereignis-IDs ohne Kontext interpretieren","symptom":"IT-Support sucht nach der Ereignis-ID, findet aber keine brauchbare Lösung","ursache":"Ereignis-ID allein ist nicht eindeutig — Quelle, Protokoll und Zeitpunkt sind entscheidend","diagnose_schritte":["Ereignisanzeige öffnen und das betroffene Protokoll (Anwendung, System, Sicherheit) identifizieren","Doppelklick auf das Ereignis — Quelle, Ereignis-ID und Beschreibung notieren","Alle vier Parameter zusammen suchen (z. B. „Ereignis-ID 10016 Quelle DistributedCOM\\")"],"loesung":"- Vollständige Ereignisdetails (inkl. XML-Ansicht) in die Websuche übernehmen\\n  - Microsoft Learn nach der Quelle und ID durchsuchen","praevention":"Immer Quelle + Protokoll + Ereignis-ID + Zeitstempel gemeinsam dokumentieren\\n\\n---"},{"titel":"Registry ohne Backup ändern","symptom":"System startet nach einer Registry-Änderung nicht mehr oder verhält sich fehlerhaft","ursache":"Änderung ohne vorheriges Exportieren des betroffenen Registry-Zweigs","diagnose_schritte":["Prüfen, ob ein .reg-Backup der Änderung vorhanden ist","Falls vorhanden: System in den abgesicherten Modus starten und das Backup per Doppelklick zurückspielen","Falls nicht vorhanden: Systemwiederherstellung oder letzte bekannte gute Konfiguration versuchen"],"loesung":"- Registry-Editor → Datei → Exportieren → betroffenen Zweig als .reg speichern\\n  - Alternativ: Systemwiederherstellungsstelle erstellen („Systemsteuerung → System → Systemschutz\\")\\n  - Erst nach erfolgreichem Backup die Änderung vornehmen","praevention":"Nie ohne Backup an der Registry arbeiten — die Änderung ist erst dann sicher, wenn ein Rollback möglich ist\\n\\n---"},{"titel":"Kritischen Dienst deaktivieren oder stoppen","symptom":"Nach dem Stoppen oder Deaktivieren eines Diensts funktioniert ein anderes Systemfeature nicht mehr","ursache":"Abhängigkeiten zwischen Diensten nicht geprüft, bevor ein Dienst deaktiviert wurde","diagnose_schritte":["services.msc öffnen und den betroffenen Dienst auswählen","Registerkarte „Abhängigkeiten\\" prüfen — zeigt, welche anderen Dienste von diesem abhängen","Prüfen, ob ein abhängiger Dienst noch funktioniert"],"loesung":"- Dienst wieder starten (manuell oder über `sc start <Dienstname>`)\\n  - Starttyp auf „Automatisch\\" zurücksetzen, falls erforderlich\\n  - Abhängigkeiten im Ticket dokumentieren, um zukünftige Probleme zu vermeiden","praevention":"Vor jeder Änderung an Diensten immer die Registerkarte „Abhängigkeiten\\" prüfen\\n\\n---"},{"titel":"Task-Manager-Daten falsch interpretieren","symptom":"Falsche Diagnose — ein harmloser Prozess wird als Problem identifiziert und beendet","ursache":"Keine Kenntnis der Windows-Systemprozesse; Prozessnamen werden nicht korrekt eingeordnet","diagnose_schritte":["Prozessnamen in einer Suchmaschine prüfen (z. B. „svchost.exe\\" oder „Runtime Broker\\")","Rechtsklick auf den Prozess → „Dateispeicherort öffnen\\" — zeigt die zugrunde liegende ausführbare Datei","Den Prozess über die Registerkarte „Details\\" mit dem Task-Manager von Process Explorer (Microsoft Sysinternals) vergleichen"],"loesung":"- Kritische Systemprozesse (csrss.exe, wininit.exe, services.exe, lsass.exe, svchost.exe) niemals beenden\\n  - „Task beenden\\" nur bei Anwendungen mit freigewähltem Namen und bekanntem Hintergrund\\n  - Bei Unsicherheit: Prozessnamen recherchieren, bevor gehandelt wird","praevention":"Vor dem Beenden eines Prozesses immer prüfen, ob es sich um einen Windows-Systemprozess handelt\\n\\n---"}],"quiz":[{"nummer":1,"frage":"Wie startest du die Ereignisanzeige am schnellsten über die Tastatur?","optionen":["Windows-Taste + X → Ereignisanzeige","Windows-Taste + R → `eventvwr.msc` → Enter","Strg+Umschalt+Esc → Ereignisanzeige","Windows-Taste + E → Ereignisanzeige"],"antwort":1,"erklaerung":"Der Ausführen-Dialog mit `eventvwr.msc` ist der schnellste Weg."},{"nummer":2,"frage":"Was solltest du VOR jeder Änderung an der Registry tun?","optionen":["Den Computer neu starten","Den betroffenen Registry-Zweig als .reg-Datei exportieren","Den Task-Manager öffnen","Nichts — die Registry ist sicher"],"antwort":1,"erklaerung":"Ein Backup (Exportieren) ist zwingend erforderlich, da falsche Änderungen das System unstartbar machen können."},{"nummer":3,"frage":"Welcher Befehl zeigt den Status aller Dienste über die Befehlszeile an?","optionen":["`service list`","`sc query`","`net status`","`svc show`"],"antwort":1,"erklaerung":"`sc query` listet alle Dienste mit ihrem aktuellen Status auf."},{"nummer":4,"frage":"Ein Prozess in deiner Umgebung hat 100 % CPU-Auslastung. Was ist der erste Schritt, bevor du ihn beendest?","optionen":["Sofort „Task beenden\\" klicken","Den Prozessnamen recherchieren und „Dateispeicherort öffnen\\" prüfen","Den Computer neu starten","Den Task-Manager schließen"],"antwort":1,"erklaerung":"Bevor ein Prozess beendet wird, muss geprüft werden, ob es sich um einen kritischen Systemprozess handelt."},{"nummer":5,"frage":"Wo findest du die Abhängigkeiten eines Diensts, bevor du ihn deaktivierst?","optionen":["Task-Manager → Start","Ereignisanzeige → System","services.msc → Diensteigenschaften → Registerkarte „Abhängigkeiten\\"","Ressourcenüberwachung → Datenträger"],"antwort":2,"erklaerung":"Die Registerkarte „Abhängigkeiten\\" in den Diensteigenschaften zeigt, welche anderen Dienste von diesem abhängen."}],"ticket":[{"situation":"Ein Mitarbeiter meldet: „Mein PC startet seit gestern extrem langsam. Nach dem Login sind alle Programme träge. Außerdem geht der Bildschirm nach einigen Minuten schwarz, und ich muss neu starten. Das Problem trat nach einem Windows-Update auf.\\"","aufgabe":"1. Welche Windows-Tools nutzt du für die Diagnose und in welcher Reihenfolge?\\n2. Was prüfst du in der Ereignisanzeige?\\n3. Wie identifizierst du den oder die Prozess(e), die die hohe CPU- oder Datenträgerauslastung verursachen?\\n4. Wie gehst du vor, wenn du einen Treiber als Ursache vermutest?","loesung":"**1. Diagnose-Reihenfolge:**\\n\\n1. **Task-Manager** → sofortige Einschätzung: CPU-, RAM-, Datenträger-Auslastung; Top-Prozesse identifizieren\\n2. **Ereignisanzeige** → System- und Anwendungsprotokolle der letzten Stunde/den letzten Stunden nach Fehlern filtern; Ereignis-IDs und Quellen notieren\\n3. **Ressourcenüberwachung** (`resmon.msc`) → detaillierte Analyse, welche Prozesse Datei- oder Netzwerkzugriffe ausführen\\n4. **Leistungsmonitor** → falls das Problem intermittierend auftritt, einen Datensammler-Satz über einen längeren Zeitraum aufzeichnen\\n5. **Dienste** → prüfen, ob der Windows Update-Dienst (wuauserv) noch aktiv ist oder hängt\\n\\n**2. Ereignisanzeige prüfen:**\\n- „Windows-Protokolle → System\\" → Filter auf „Fehler\\" und „Warnung\\" der letzten 24–48 Stunden\\n- „Windows-Protokolle → Anwendung\\" → Anwendungsfehler, die auf fehlgeschlagene Updates oder Treiber hinweisen\\n- Typische Ereignis-IDs nach Updates: „Kernel-General\\", „Kernel-Power\\" (bei schwarzem Bildschirm = möglicher Absturz), „DistributedCOM\\"\\n- Auf „Kritisch\\" prüfen — ein Eintrag bei „Kernel-Power\\" mit Code 41 deuten auf einen Plug-and-Play-Absturz hin\\n\\n**3. Prozessidentifikation:**\\n- Task-Manager → Registerkarte „Details\\" → Spalte „CPU\\" oder „Datenträger\\" sortieren\\n- Rechtsklick auf den Top-Prozess → „Dateispeicherort öffnen\\" → zeigt den Pfad der ausführbaren Datei\\n- Prüfen, ob der Pfad zu einer bekanntem Windows-Komponente oder zu einer Drittanbieter-Anwendung zeigt\\n- Bei `svchost.exe`: Rechtsklick → „Wechseln zu Diensten\\" — zeigt, welche Dienste unter diesem Prozess laufen\\n- Prozessnamen recherchieren, falls unbekannt\\n\\n**4. Treiber als Ursache vermuten:**\\n- Geräte-Manager öffnen (Windows-Taste + X → Geräte-Manager)\\n- Auf Ausrufezeichen oder rote Markierungen prüfen\\n- Bei verdächtigem Treiber: Rechtsklick → „Eigenschaften\\" → Registerkarte „Treiber\\" → „Treiber zurücksetzen\\" (falls verfügbar) oder „Treiber deaktivieren\\"\\n- Letzter funktionierender Treiber wird automatisch installiert\\n- Alternativ: Windows-Update erneut ausführen (manuell nach aktuellen Treibern suchen)\\n- Falls das Problem nach einem bestimmten Update auftrat: „Einstellungen → Windows Update → Updateverlauf → Updates deinstallieren\\" → das betroffene Update entfernen\\n\\n---"}],"slug":"modul-9-windows-tiefe"}]');export{e as t};